function downloadTextFile(filename, text){
  var blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a); a.click();
  setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}
async function uploadDeleteListToCloudinary(folder, filename, text){
  /* Ghi file lệnh xóa vào cùng thư mục trên Cloudinary (best-effort: preset chỉ
     cho ảnh thì bước này lỗi, app vẫn chạy tiếp và thầy dùng bản tải về). */
  try {
    var cName = (S.cloudinaryCloudName || localStorage.getItem('chambai_cname') || '').trim();
    var cPreset = (S.cloudinaryPreset || localStorage.getItem('chambai_cpreset') || '').trim();
    if (!cName || !cPreset) return false;
    var fd = new FormData();
    fd.append('file', new Blob([text], { type: 'text/plain' }), filename);
    fd.append('upload_preset', cPreset);
    /* Nhung slug vao public_id nhu anh (preset thang tham so folder). */
    var _parts = (folder || '').split('/');
    var _slug = _parts.length > 1 ? _parts[_parts.length - 1] : '';
    fd.append('folder', 'anhchamtracnghiem');
    fd.append('public_id', (_slug ? _slug + '/' : '') + filename.replace(/\.[^.]+$/, ''));
    var res = await fetch('https://api.cloudinary.com/v1_1/' + encodeURIComponent(cName) + '/raw/upload', { method: 'POST', body: fd });
    return res.ok;
  } catch (e){ return false; }
}

async function sha1Hex(str){
  if (window.crypto && window.crypto.subtle){
    var enc = new TextEncoder();
    var buf = await window.crypto.subtle.digest('SHA-1', enc.encode(str));
    return Array.from(new Uint8Array(buf)).map(function(b){ return b.toString(16).padStart(2, '0'); }).join('');
  }
  throw new Error('Trình duyệt không hỗ trợ Web Crypto SHA-1');
}

async function cloudinaryDestroyPhoto(cloudName, publicId, apiKey, apiSecret){
  var timestamp = Math.floor(Date.now() / 1000);
  var toSign = 'public_id=' + publicId + '&timestamp=' + timestamp + apiSecret;
  var signature = await sha1Hex(toSign);
  var fd = new FormData();
  fd.append('public_id', publicId);
  fd.append('api_key', apiKey);
  fd.append('timestamp', timestamp);
  fd.append('signature', signature);
  var res = await fetch('https://api.cloudinary.com/v1_1/' + encodeURIComponent(cloudName) + '/image/destroy', {
    method: 'POST',
    body: fd
  });
  if (!res.ok){
    var errData = await res.json().catch(function(){ return {}; });
    var errMsg = (errData.error && errData.error.message) ? errData.error.message : ('HTTP ' + res.status);
    throw new Error(errMsg);
  }
  var data = await res.json();
  return data.result === 'ok' || data.result === 'not found';
}

async function fetchCloudinaryExamResources(cloudName, apiKey, apiSecret, examName){
  if (!cloudName || !apiKey || !apiSecret || !examName) return [];
  var slug = slugify(examName);
  var prefixes = [];
  if (slug) prefixes.push('anhchamtracnghiem/' + slug);
  if (examName && examName !== slug) prefixes.push('anhchamtracnghiem/' + examName);
  if (slug) prefixes.push(slug);
  var found = [];
  var seenIds = {};

  for (var i = 0; i < prefixes.length; i++){
    var pfx = prefixes[i];
    try {
      var url = '/api/cloudinary/resources?cloudName=' + encodeURIComponent(cloudName) +
        '&apiKey=' + encodeURIComponent(apiKey) +
        '&apiSecret=' + encodeURIComponent(apiSecret) +
        '&prefix=' + encodeURIComponent(pfx);
      var res = await fetch(url);
      if (res.ok){
        var data = await res.json();
        if (data && Array.isArray(data.resources)){
          data.resources.forEach(function(r){
            if (r && r.public_id && !seenIds[r.public_id]){
              seenIds[r.public_id] = true;
              found.push({ id: r.public_id, link: r.secure_url || r.url });
            }
          });
        }
      }
    } catch(e){
      console.warn('Lỗi quét ảnh Cloudinary theo prefix:', pfx, e);
    }
  }
  return found;
}

