function normMade(m){ return String(m==null?'':m).trim().replace(/^0+/,'') || '0'; }
function normSbd(s){ return String(s==null?'':s).trim(); }
function normNum(v){
  if (v==null || v==='') return null;
  let s = String(v).trim().replace(/\s+/g,'').replace(',', '.');
  if (/^[+-]?(\d+\.?\d*|\.\d+)$/.test(s)) return parseFloat(s);
  return s;
}
function sameShort(a, b){
  const na = normNum(a), nb = normNum(b);
  if (typeof na === 'number' && typeof nb === 'number') return Math.abs(na - nb) < 1e-9;
  return String(a==null?'':a).trim() === String(b==null?'':b).trim();
}
function p2Score(nCorrect, p2, mode){
  if (mode === 'all') return nCorrect === 4 ? p2 : 0;
  if (mode === 'even') return p2 * nCorrect / 4;
  const table = {0:0, 1:0.1, 2:0.25, 3:0.5, 4:1.0};
  return p2 * (table[nCorrect] || 0);
}
function scorePaper(ans, key, cfg){
  // ans: {p1:[...], p2:[['D','S',...]...], p3:[...]} ; key: {made, p1, p2, p3} with null = not counted, 'E' = lỗi đề (tính điểm tối đa dù HS làm thế nào)
  let s1 = 0, s2 = 0, s3 = 0, max = 0, counted = 0;
  for (let i = 0; i < cfg.n1; i++){
    const k = key.p1[i];
    if (k == null) continue;
    counted++; max += cfg.p1;
    if (k === 'E') s1 += cfg.p1; // câu lỗi đề: cho điểm tối đa
    else if (ans.p1[i] && ans.p1[i] === k) s1 += cfg.p1;
  }
  for (let i = 0; i < cfg.n2; i++){
    const k = key.p2[i];
    if (k == null) continue;
    counted++; max += cfg.p2;
    const a = ans.p2[i] || [];
    let nc = 0;
    for (let j = 0; j < 4; j++){
      if (k[j] === 'E'){ nc++; continue; } // ý lỗi đề: tính như HS trả lời đúng
      if (a[j] && a[j] === k[j]) nc++;
    }
    s2 += p2Score(nc, cfg.p2, cfg.mode2); // p2Score(0) = 0 ở mọi chế độ nên câu bỏ trống vẫn 0 như trước
  }
  for (let i = 0; i < cfg.n3; i++){
    const k = key.p3[i];
    if (k == null) continue;
    counted++; max += cfg.p3;
    if (k === 'E') s3 += cfg.p3; // câu lỗi đề: cho điểm tối đa
    else if (ans.p3[i] != null && ans.p3[i] !== '' && sameShort(ans.p3[i], k)) s3 += cfg.p3;
  }
  const raw = s1 + s2 + s3;
  const scaled = max > 0 ? raw / max * cfg.scale : 0;
  return { s1, s2, s3, raw, max, scaled: Math.round(scaled * 100) / 100, counted };
}
function p3Reconstruct(minus, commaPos, digits){
  // digits: array of 4 (digit string or null) in position order; commaPos: 2|3|null (position index 1-based where comma sits)
  let out = '';
  for (let pos = 1; pos <= 4; pos++){
    if (commaPos === pos) out += ',';
    if (digits[pos-1] != null) out += digits[pos-1];
  }
  out = out.replace(/,+$/, '');
  if (out === '' || out === ',') return null;
  return (minus ? '-' : '') + out;
}
