function parseCustomGrid(txt){
  var g = { sbd: [], made: [], pi: [], pii: [], piii: [], radius: 0.0075 };
  for (var i = 0; i < 10; i++){ g.sbd.push(new Array(8).fill(null)); g.made.push(new Array(4).fill(null)); }
  for (var b = 0; b < 4; b++){
    var blk = [];
    for (var r = 0; r < 10; r++) blk.push(new Array(4).fill(null));
    g.pi.push(blk);
  }
  for (var b2 = 0; b2 < 8; b2++){
    var blk2 = [];
    for (var r2 = 0; r2 < 4; r2++) blk2.push(new Array(4).fill(null));
    g.pii.push(blk2);
  }
  for (var q = 0; q < 6; q++) g.piii.push({ minus: null, commas: [null, null], digits: Array.from({ length: 10 }, function(){ return new Array(4).fill(null); }) });
  function isIntTok(t){ return /^\d+$/.test(t); }
  function applyBlock(kind, idx, x0, y0, dx, dy){
    var r, c;
    if (kind === 'SBD'){ for (r = 0; r < 10; r++) for (c = 0; c < 8; c++) g.sbd[r][c] = [x0 + c * dx, y0 + r * dy]; }
    else if (kind === 'MADE'){ for (r = 0; r < 10; r++) for (c = 0; c < 4; c++) g.made[r][c] = [x0 + c * dx, y0 + r * dy]; }
    else if (kind === 'PI'){ for (r = 0; r < 10; r++) for (c = 0; c < 4; c++) g.pi[idx][r][c] = [x0 + c * dx, y0 + r * dy]; }
    else if (kind === 'PII'){ for (r = 0; r < 4; r++) for (c = 0; c < 4; c++) g.pii[idx][r][c] = [x0 + c * dx, y0 + r * dy]; }
    else if (kind === 'PIII'){
      var qq = g.piii[idx];
      qq.minus = [x0, y0];
      qq.commas = [[x0 + dx, y0 + dy], [x0 + 2 * dx, y0 + dy]];
      for (r = 0; r < 10; r++) for (c = 0; c < 4; c++) qq.digits[r][c] = [x0 + c * dx, y0 + (r + 2) * dy];
    }
  }
  var errs = [];
  txt.split(/\n/).forEach(function(ln, li){
    var t = ln.trim(); if (!t || t[0] === '#') return;
    var p = t.split(/\s+/);
    try {
      if (p[0] === 'RADIUS' && p.length === 2){ g.radius = parseFloat(p[1]); return; }
      var m;
      if ((m = /^(PI|PII|PIII)(\d)$/.exec(p[0])) && p.length === 5){
        var kind = m[1], idx = +m[2] - 1;
        if (kind === 'PI' && (idx < 0 || idx > 3)) throw new Error('lô ' + p[0] + ' ngoài 1-4');
        if (kind === 'PII' && (idx < 0 || idx > 7)) throw new Error('lô ' + p[0] + ' ngoài 1-8');
        if (kind === 'PIII' && (idx < 0 || idx > 5)) throw new Error('lô ' + p[0] + ' ngoài 1-6');
        applyBlock(kind, idx, +p[1], +p[2], +p[3], +p[4]); return;
      }
      if ((p[0] === 'SBD' || p[0] === 'MADE') && p.length === 5 && !isIntTok(p[1])){
        applyBlock(p[0], 0, +p[1], +p[2], +p[3], +p[4]); return;
      }
      if (p[0] === 'SBD' && p.length === 5){ g.sbd[+p[1]][+p[2]] = [+p[3], +p[4]]; return; }
      if (p[0] === 'MADE' && p.length === 5){ g.made[+p[1]][+p[2]] = [+p[3], +p[4]]; return; }
      if (p[0] === 'PI' && p.length === 6){ g.pi[+p[1]][+p[2]][+p[3]] = [+p[4], +p[5]]; return; }
      if (p[0] === 'PII' && p.length === 6){ g.pii[+p[1]][+p[2]][+p[3]] = [+p[4], +p[5]]; return; }
      if (p[0] === 'PIII' && p.length >= 5){
        var qq = +p[1];
        if (p[2] === 'MINUS'){ g.piii[qq].minus = [+p[3], +p[4]]; return; }
        if (p[2] === 'COMMA1'){ g.piii[qq].commas[0] = [+p[3], +p[4]]; return; }
        if (p[2] === 'COMMA2'){ g.piii[qq].commas[1] = [+p[3], +p[4]]; return; }
        if (p[2] === 'D' && p.length === 7){ g.piii[qq].digits[+p[3]][+p[4]] = [+p[5], +p[6]]; return; }
      }
      errs.push('dòng ' + (li + 1) + ': không hiểu "' + t + '"');
    } catch (e){ errs.push('dòng ' + (li + 1) + ': ' + e.message); }
  });
  function countNull(a){ var n = 0; (function walk(x){ if (Array.isArray(x)) x.forEach(walk); else if (x === null || x === undefined) n++; })(a); return n; }
  /* FIX 2026-11-07 (lỗi sau khi xóa myGrids): parse luôn tạo 8 lô PII nhưng lưới chỉ
     định nghĩa PII1–4 nên PII5–8 toàn null; drawCalib() vẽ tới ô null thì throw làm
     mất ô nhập góc + nút góc + bảng điểm. Cắt các lô PII null ở cuối, chỉ giữ lô có dữ liệu. */
  while (g.pii.length > 0 && countNull(g.pii[g.pii.length - 1]) === 16) g.pii.pop();
  var missing = [];
  function blockMissing(name, cells){ if (countNull(cells)) missing.push('thiếu lô ' + name); }
  blockMissing('SBD', g.sbd); blockMissing('MADE', g.made);
  for (var bi = 0; bi < 4; bi++){ blockMissing('PI' + (bi + 1), g.pi[bi]); blockMissing('PII' + (bi + 1), g.pii[bi]); }
  for (var qi = 0; qi < 6; qi++){ var qq3 = g.piii[qi]; if (!qq3.minus || countNull(qq3.commas) || countNull(qq3.digits)) missing.push('thiếu lô PIII' + (qi + 1)); }
  return { grid: g, errs: errs, missing: missing };
}

function gridToParams(g){
  function blk(cells){ var r0 = cells[0], r1 = cells[cells.length - 1]; return [r0[0][0], r0[0][1], (r0[r0.length - 1][0] - r0[0][0]) / (r0.length - 1), (r1[0][1] - r0[0][1]) / (cells.length - 1)]; }
  var prm = { RADIUS: g.radius || 0.0075, SBD: blk(g.sbd), MADE: blk(g.made), PI: [], PII: [], PIII: [] };
  for (var b = 0; b < 4; b++){ prm.PI.push(blk(g.pi[b])); prm.PII.push(blk(g.pii[b])); }
  for (var q = 0; q < 6; q++){ var qq = g.piii[q]; prm.PIII.push([qq.minus[0], qq.minus[1], (qq.digits[0][3][0] - qq.digits[0][0][0]) / 3, (qq.digits[9][0][1] - qq.minus[1]) / 11]); }
  return prm;
}

function paramsToGrid(prm){
  var g = { sbd: [], made: [], pi: [], pii: [], piii: [], radius: prm.RADIUS || 0.0075 };
  function fill(rows, cols, x0, y0, dx, dy){ var out = []; for (var r = 0; r < rows; r++){ var row = []; for (var c = 0; c < cols; c++) row.push([x0 + c * dx, y0 + r * dy]); out.push(row); } return out; }
  g.sbd = fill(10, 8, prm.SBD[0], prm.SBD[1], prm.SBD[2], prm.SBD[3]);
  g.made = fill(10, 4, prm.MADE[0], prm.MADE[1], prm.MADE[2], prm.MADE[3]);
  for (var b = 0; b < 4; b++){ g.pi.push(fill(10, 4, prm.PI[b][0], prm.PI[b][1], prm.PI[b][2], prm.PI[b][3])); g.pii.push(fill(4, 4, prm.PII[b][0], prm.PII[b][1], prm.PII[b][2], prm.PII[b][3])); }
  for (var q = 0; q < 6; q++){ var P = prm.PIII[q]; g.piii.push({ minus: [P[0], P[1]], commas: [[P[0] + P[2], P[1] + P[3]], [P[0] + 2 * P[2], P[1] + P[3]]], digits: fill(10, 4, P[0], P[1] + 2 * P[3], P[2], P[3]) }); }
  return g;
}

function gridBlockArr(prm, name){
  if (name === 'SBD') return prm.SBD;
  if (name === 'MADE') return prm.MADE;
  var m = /^(PI|PII|PIII)(\d)$/.exec(name); if (!m) return null;
  return prm[m[1]][+m[2] - 1];
}

