function isOlmTemplate(tid){
  tid = tid || (S.exam && S.exam.templateId) || '';
  if (tid === 'OLM_DenTrang' || tid === 'wFAOnW2DLbBZOaXyo0Wh') return true;
  if (tid === 'A4_BGD' || tid === 'a4tl' || tid === 'bgd2025' || tid === 'xPxDMlNvR1Oc6TVqonxC' || tid === 'tr9fY91f6VZLZOFJczQb') return false;
  try {
    var t = (S.templates || []).find(function(x){ return x.id === tid; });
    var nm = (t && t.name) ? t.name : tid;
    if (/OLM/i.test(nm)) return true;
    if (/A4|BGD|TLTN/i.test(nm)) return false;
  } catch(e){}
  /* Mẫu lạ mặc định theo A4_BGD (mẫu chuẩn quốc gia phổ biến nhất) */
  return false;
}


