function curGrid(){
  if (S.liveGrid) { S._gridSource = 'live (đang sửa)'; return S.liveGrid; }

  var tid = S.exam && S.exam.templateId;
  var isOlm = isOlmTemplate(tid);

  // 1. Lưới riêng của bài kiểm tra (nếu GV đã sửa tay riêng cho bài này và không phải bản cũ 0.7005)
  if (S.exam && S.exam.customGridJson){
    try {
      if (!S.exam._customGrid) S.exam._customGrid = JSON.parse(S.exam.customGridJson);
      var cg = S.exam._customGrid;
      if (cg && cg.sbd && cg.sbd[0] && cg.sbd[0][0] && Math.abs(cg.sbd[0][0][0] - 0.7005) > 0.005){
        S._gridSource = 'lưới riêng của bài (đã sửa tay)';
        return cg;
      }
    } catch(e){}
  }

  // 2. Lưới riêng của thầy theo mẫu phiếu (nếu có lưu và không phải bản cũ 0.7005)
  try {
    if (tid && S.user){
      var _raw = getMyGrid(tid);
      if (_raw){
        if (!S._myGridCache) S._myGridCache = {};
        if (!S._myGridCache[tid]) S._myGridCache[tid] = (typeof _raw === 'string') ? JSON.parse(_raw) : _raw;
        var mg = S._myGridCache[tid];
        if (mg && mg.sbd && mg.sbd[0] && mg.sbd[0][0] && Math.abs(mg.sbd[0][0][0] - 0.7005) > 0.005){
          S._gridSource = 'lưới riêng của thầy (' + tid + ')';
          return mg;
        }
      }
    }
  } catch(e){}

  // 3. Lưới mặc định chuẩn trong code theo mẫu phiếu (thầy chốt 2026-11-06)
  if (isOlm){
    S._gridSource = 'lưới chuẩn OLM_DenTrang';
    return PARSED_DEFAULT_GRIDS['OLM_DenTrang'];
  }
  S._gridSource = 'lưới chuẩn A4_BGD';
  return PARSED_DEFAULT_GRIDS['A4_BGD'];
}
