/* 0811them4: Gioi han bai cham/nam RIENG theo tung GV (admin dat o bang Quan ly GV).
   Doc teachers/{idgv}.yearlyGradeLimit; chua dat hoac sai thi dung mac dinh 5000
   (YEARLY_GRADE_LIMIT). Doc moi lan check de admin doi xong la ap dung ngay,
   khong can GV dang xuat/dang nhap lai. */
async function getYearlyLimit(){
  try {
    if (S.user && typeof S.user.yearlyGradeLimit === 'number' && S.user.yearlyGradeLimit > 0) return Math.floor(S.user.yearlyGradeLimit);
    if (S.user && S.user.idgv && S.user.idgv !== 'ADMIN'){
      var doc = await db.collection('teachers').doc(S.user.idgv).get();
      if (doc.exists){
        var v = doc.data().yearlyGradeLimit;
        if (typeof v === 'number' && v > 0){
          S.user.yearlyGradeLimit = Math.floor(v);
          return Math.floor(v);
        }
      }
    }
  } catch(e){}
  return YEARLY_GRADE_LIMIT;
}
