  if (ref && ref === phone){ msg('authMsg', 'Không được tự giới thiệu chính mình.', 'err'); return; }
  var refDoc = await db.collection('teachers').doc(phone).get();
  if (refDoc.exists){ msg('authMsg', 'Số điện thoại này đã có tài khoản, thầy đăng nhập nhé.', 'err'); return; }
