  if (!others.length){ wrap.innerHTML = '<p class="muted">Chưa có bài kiểm tra khác có đáp án để chép.</p>'; return; }
  var html = '<h3>Chép đáp án từ bài kiểm tra khác</h3><p class="muted">Đáp án của bài được chọn sẽ chép sang bài này (mã đề trùng sẽ bị ghi đè).</p><div class="row"><select id="keyPickSel">' +
    others.map(function(e){ return '<option value="' + esc(e.id) + '">' + esc(e.name) + ' (' + Object.keys(e.keys).length + ' mã đề)</option>'; }).join('') +
    '</select><button id="keyCopyBtn" class="secondary">📋 Chép đáp án</button></div>';
  wrap.innerHTML = html;
