$('btnImportSt').onclick = function(){ if (needExam()) $('fileSt').click(); };
$('fileSt').onchange = function(){
  var f = this.files[0]; if (!f) return;
  var rd = new FileReader();
  rd.onload = async function(){
    try {
      var wb = XLSX.read(new Uint8Array(rd.result), { type: 'array' });
      var ws = wb.Sheets[wb.SheetNames[0]];
      var rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false });
      var parsed = parseStudentSheet(rows);
      if (parsed.err){ msg('stMsg', parsed.err, 'err'); return; }
      var added = 0, dups = 0, capped = 0;
      var have = {}; S.students.forEach(function(s){ have[normSbd(s.sbd)] = 1; });
      parsed.list.forEach(function(st){
        if (have[st.sbd]){ dups++; return; }
        if (freeStudentRoom() === 0){ capped++; return; }
        have[st.sbd] = 1;
        S.students.push(st);
        added++;
      });
      await saveExam(); renderStudents();
      msg('stMsg', 'Import xong: thêm <b>' + added + '</b> học sinh' + (dups ? ', trùng SBD bỏ qua ' + dups : '') + (parsed.skipped ? ', dòng trống bỏ qua ' + parsed.skipped : '') + (capped ? ', vượt giới hạn 10 học sinh của tài khoản thường nên bỏ qua ' + capped : '') + '.', 'okbox');
    } catch (e){ msg('stMsg', 'Đọc file lỗi: ' + esc(e.message), 'err'); }
  };
  rd.readAsArrayBuffer(f); this.value = '';
};
$('btnAddSt').onclick = async function(){
  if (!needExam()) return;
  var sbd = normSbd($('stAddSbd').value), name = $('stAddName').value.trim();
  if (!sbd || !name){ alert('Nhập đủ SBD và họ tên.'); return; }
  if (S.students.some(function(s){ return normSbd(s.sbd) === sbd; })){ alert('SBD này đã có trong danh sách.'); return; }
  if (freeStudentRoom() === 0){ alert('Tài khoản thường mỗi bài chỉ có tối đa 10 học sinh. Thầy nâng cấp VIP để thêm không giới hạn.'); return; }
  S.students.push({ sbd: sbd, name: name, class: $('stAddClass').value.trim(), dob: '', room: '', code: '' });
  await saveExam(); renderStudents();
  $('stAddSbd').value = ''; $('stAddName').value = ''; $('stAddClass').value = '';
};

/* ================= ANSWER KEYS ================= */
$('btnDlAkTemplate').onclick = function(){
  if (!needExam()) return;
  var cfg = S.exam.config;
  var head = ['Câu', '101', '102'];
  var aoa = [head];
  for (var q = 1; q <= cfg.n1 + cfg.n2 + cfg.n3; q++){
    var row = [q];
    if (q <= cfg.n1) row.push('A', 'B');
    else if (q <= cfg.n1 + cfg.n2) row.push('SDSS', 'DSSD');
    else row.push('12,5', '60');
    aoa.push(row);
  }
  var ws = XLSX.utils.aoa_to_sheet(aoa);
  ws['!cols'] = [{ wch: 6 }, { wch: 12 }, { wch: 12 }];
  var wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, ws, 'DapAn');
  XLSX.writeFile(wb, 'Mau_DapAn_' + S.exam.name + '.xlsx');
};
$('btnImportAk').onclick = function(){ if (needExam()) $('fileAk').click(); };
$('fileAk').onchange = function(){
  var f = this.files[0]; if (!f) return;
  var rd = new FileReader();
  rd.onload = async function(){
    try {
      var wb = XLSX.read(new Uint8Array(rd.result), { type: 'array' });
      var ws = wb.Sheets[wb.SheetNames[0]];
      var rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false });
      var hi = -1, madeCols = [];
      for (var r = 0; r < rows.length; r++){
        var row = rows[r] || [];
        if (String(row[0] || '').trim().toLowerCase() === 'câu'){
          hi = r;
          for (var c = 1; c < row.length; c++){
            var m = String(row[c] || '').trim();
            if (m) madeCols.push({ col: c, made: m });
          }
          break;
        }
      }
      if (hi < 0 || !madeCols.length){ msg('akMsg', 'File phải có hàng tiêu đề: cột đầu là "Câu", các cột sau là mã đề.', 'err'); return; }
      var cfg = S.exam.config;
      var keys = {};
      madeCols.forEach(function(mc){
        keys[normMade(mc.made)] = { made: mc.made, p1: [], p2: [], p3: [] };
      });
      var nQ = cfg.n1 + cfg.n2 + cfg.n3;
      for (var i = hi + 1; i < rows.length; i++){
        var row = rows[i] || [];
        var q = parseInt(row[0]);
        if (!q || q < 1 || q > nQ) continue;
        madeCols.forEach(function(mc){
          var v = row[mc.col];
          var k = keys[normMade(mc.made)];
          if (v == null || String(v).trim() === '') return; // ô trống: mã đề này không có câu đó
          v = String(v).trim();
          if (q <= cfg.n1){
            k.p1[q - 1] = v.toUpperCase().replace(/[^ABCDE]/g, '').charAt(0) || null;
          } else if (q <= cfg.n1 + cfg.n2){
            var s = v.toUpperCase().replace(/[^DSĐE]/g, '').replace(/Đ/g, 'D');
            // Lưu dạng chuỗi 'SDSS' (Firestore cấm mảng lồng trong mảng)
            if (s.length === 4) k.p2[q - cfg.n1 - 1] = s;
          } else {
            k.p3[q - cfg.n1 - cfg.n2 - 1] = (v.toUpperCase() === 'E') ? 'E' : v;
          }
        });
      }
      // lấp đầy mảng cho đủ số câu (thiếu = null = không tính)
      Object.keys(keys).forEach(function(mk){
        var k = keys[mk];
        for (var i = 0; i < cfg.n1; i++) if (k.p1[i] === undefined) k.p1[i] = null;
        for (var i = 0; i < cfg.n2; i++) if (k.p2[i] === undefined) k.p2[i] = null;
        for (var i = 0; i < cfg.n3; i++) if (k.p3[i] === undefined) k.p3[i] = null;
      });
      S.keys = keys; await saveExam(); renderKeys();
      msg('akMsg', 'Import xong đáp án cho <b>' + Object.keys(keys).length + '</b> mã đề: ' + Object.keys(keys).map(function(mk){ return keys[mk].made; }).join(', ') + '.', 'okbox');
    } catch (e){ msg('akMsg', 'Đọc file lỗi: ' + esc(e.message), 'err'); }
  };
  rd.readAsArrayBuffer(f); this.value = '';
};
function renderKeys(){
  if (!S.exam){ $('akTableWrap').innerHTML = '<p class="muted">Thầy mở một bài kiểm tra ở tab "Bài kiểm tra" trước nhé.</p>'; renderKeyPicker(); return; }
  var cfg = S.exam.config;
  var mades = Object.keys(S.keys);
  if (!mades.length){ $('akTableWrap').innerHTML = '<p class="muted">Chưa có đáp án. Thầy import file Excel đáp án ở trên.</p>'; renderKeyPicker(); return; }
  var html = '<table><thead><tr><th>Câu</th><th>Phần</th>' + mades.map(function(mk){ return '<th>' + esc(S.keys[mk].made) + '</th>'; }).join('') + '</tr></thead><tbody>';
  for (var q = 1; q <= cfg.n1 + cfg.n2 + cfg.n3; q++){
    var part = q <= cfg.n1 ? 'I' : (q <= cfg.n1 + cfg.n2 ? 'II' : 'III');
    html += '<tr><td>' + q + '</td><td>' + part + '</td>';
    mades.forEach(function(mk){
      var k = S.keys[mk], v = '';
      if (part === 'I') v = k.p1[q - 1] || '—';
      else if (part === 'II') v = k.p2[q - cfg.n1 - 1] || '—';
      else v = k.p3[q - cfg.n1 - cfg.n2 - 1] == null ? '—' : esc(k.p3[q - cfg.n1 - cfg.n2 - 1]);
      html += '<td>' + v + '</td>';
    });
    html += '</tr>';
  }
  html += '</tbody></table>';
  $('akTableWrap').innerHTML = html;
  renderKeyPicker();
}

/* ================= OMR ENGINE ================= */
function solveHomography(src, dst){
  // src: 4 points [x,y] (page fractions), dst: 4 points [x,y] (photo px)
  var A = [], b = [];
  for (var i = 0; i < 4; i++){
    var x = src[i][0], y = src[i][1], u = dst[i][0], v = dst[i][1];
    A.push([x, y, 1, 0, 0, 0, -u * x, -u * y]); b.push(u);
    A.push([0, 0, 0, x, y, 1, -v * x, -v * y]); b.push(v);
  }
  var n = 8;
  for (var c = 0; c < n; c++){
    var piv = c;
    for (var r = c + 1; r < n; r++) if (Math.abs(A[r][c]) > Math.abs(A[piv][c])) piv = r;
    var tmp = A[c]; A[c] = A[piv]; A[piv] = tmp;
    var tb = b[c]; b[c] = b[piv]; b[piv] = tb;
    for (var r2 = c + 1; r2 < n; r2++){
      var f = A[r2][c] / A[c][c];
      for (var k = c; k < n; k++) A[r2][k] -= f * A[c][k];
      b[r2] -= f * b[c];
    }
  }
  var h = new Array(n);
  for (var r = n - 1; r >= 0; r--){
    var s = b[r];
    for (var k = r + 1; k < n; k++) s -= A[r][k] * h[k];
    h[r] = s / A[r][r];
  }
  return h; // [h0..h7], h8 = 1
}
function applyH(h, x, y){
  var d = h[6] * x + h[7] * y + 1;
  return [(h[0] * x + h[1] * y + h[2]) / d, (h[3] * x + h[4] * y + h[5]) / d];
}
/* Tự động tìm 4 ô đen ở 4 góc phiếu (ý tưởng của Thầy Nguyễn Mạnh Hùng:
   lấy tọa độ cụm điểm đen dày đặc nhất gần mỗi góc).
   Cách làm: thu nhỏ ảnh → chia vùng gần mỗi góc thành lưới ô nhỏ →
   đếm điểm đen mỗi ô → ô nào đen nhất chính là ô vuông đen → lấy trọng tâm.
   Trả về [[x1,y1]...] thứ tự TL,TR,BR,BL (tọa độ 0-1), hoặc null. */
/* Tính tâm chuẩn zin của ô vuông đen:
   - Dùng biểu đồ phân bố điểm đen FWHM (Full Width at Half Maximum) theo từng trục X và Y.
   - Nội suy viền mức 50% cường độ để triệt tiêu hoàn toàn sai lệch mờ nhòe máy quét.
   - Đảm bảo tâm 4 góc chuẩn xác đến từng phân số pixel. */
function getZinSquareCenter(gray, w, h, minX, maxX, minY, maxY, th){
  var bw = maxX - minX + 1, bh = maxY - minY + 1;
  var colCount = new Float64Array(bw);
  var rowCount = new Float64Array(bh);
  var maxCol = 0, maxRow = 0;
  var sumX = 0, sumY = 0, count = 0;

  for (var y = minY; y <= maxY; y++){
    var rOff = y * w;
    for (var x = minX; x <= maxX; x++){
      if (gray[rOff + x] < th){
        colCount[x - minX]++;
        rowCount[y - minY]++;
        sumX += x;
        sumY += y;
        count++;
      }
    }
  }
  for (var i = 0; i < bw; i++) if (colCount[i] > maxCol) maxCol = colCount[i];
  for (var j = 0; j < bh; j++) if (rowCount[j] > maxRow) maxRow = rowCount[j];

  var colCut = maxCol * 0.5;
  var rowCut = maxRow * 0.5;

  var leftEdge = minX;
  for (var x = 1; x < bw; x++){
    if (colCount[x] >= colCut){
      var denom = (colCount[x] - colCount[x - 1]) || 1;
      leftEdge = (minX + x - 1) + (colCut - colCount[x - 1]) / denom;
      break;
    }
  }
  var rightEdge = maxX;
  for (var x2 = bw - 2; x2 >= 0; x2--){
    if (colCount[x2] >= colCut){
      var denom2 = (colCount[x2] - colCount[x2 + 1]) || 1;
      rightEdge = (minX + x2) + (colCount[x2] - colCut) / denom2;
      break;
    }
  }

  var topEdge = minY;
  for (var y = 1; y < bh; y++){
    if (rowCount[y] >= rowCut){
      var denom3 = (rowCount[y] - rowCount[y - 1]) || 1;
      topEdge = (minY + y - 1) + (rowCut - rowCount[y - 1]) / denom3;
      break;
    }
  }
  var bottomEdge = maxY;
  for (var y2 = bh - 2; y2 >= 0; y2--){
    if (rowCount[y2] >= rowCut){
      var denom4 = (rowCount[y2] - rowCount[y2 + 1]) || 1;
      bottomEdge = (minY + y2) + (rowCount[y2] - rowCut) / denom4;
      break;
    }
  }

  var midX = (leftEdge + rightEdge) / 2;
  var midY = (topEdge + bottomEdge) / 2;
  var centX = count ? (sumX / count) : midX;
  var centY = count ? (sumY / count) : midY;

  return {
    cx: midX * 0.75 + centX * 0.25,
    cy: midY * 0.75 + centY * 0.25,
    bw: rightEdge - leftEdge + 1,
    bh: bottomEdge - topEdge + 1
  };
}

/* Tìm ô vuông đen theo nguyên tắc hình học chuẩn của thầy:
   - Góc 1: Điểm đen gần nhất với toạ độ O(0, 0) trên-trái.
   - Góc 2: Lấy điểm xa O nhất trên phải A(xmax, 0) rồi lấy điểm đen gần A nhất là góc 2.
   - Góc 3: Lấy điểm xa O nhất dưới phải C(xmax, ymax) rồi lấy điểm đen gần C nhất là góc 3.
   - Góc 4: Lấy điểm xa O nhất dưới trái B(0, ymax) rồi lấy điểm đen gần B nhất là góc 4. */
function findCornerByTarget(gray, w, h, targetIndex){
  // targetIndex: 0 (Góc 1: O), 1 (Góc 2: A), 2 (Góc 3: C), 3 (Góc 4: B)
  var tx = 0, ty = 0, x0 = 0, x1 = Math.round(w * 0.40), y0 = 0, y1 = Math.round(h * 0.40);
  if (targetIndex === 1){ // Góc 2: A(xmax, 0)
    tx = w - 1; ty = 0;
    x0 = Math.round(w * 0.60); x1 = w;
    y0 = 0; y1 = Math.round(h * 0.40);
  } else if (targetIndex === 2){ // Góc 3: C(xmax, ymax)
    tx = w - 1; ty = h - 1;
    x0 = Math.round(w * 0.60); x1 = w;
    y0 = Math.round(h * 0.60); y1 = h;
  } else if (targetIndex === 3){ // Góc 4: B(0, ymax)
    tx = 0; ty = h - 1;
    x0 = 0; x1 = Math.round(w * 0.40);
    y0 = Math.round(h * 0.60); y1 = h;
  }

  var thList = [80, 105, 130];
  var minDim = Math.max(8, Math.round(w * 0.007));
  var maxDim = Math.round(w * 0.065);
  var best = null, minDist = Infinity;
  var winW = x1 - x0, winH = y1 - y0;

  for (var ti = 0; ti < thList.length; ti++){
    var th = thList[ti];
    var visited = new Uint8Array(winW * winH);

    for (var y = y0; y < y1; y++){
      for (var x = x0; x < x1; x++){
        var lIdx = (y - y0) * winW + (x - x0);
        if (visited[lIdx] || gray[y * w + x] >= th) continue;

        // Bỏ qua viền đen mép máy quét (trong phạm vi 6px ngoài cùng)
        if (x <= 6 || x >= w - 7 || y <= 6 || y >= h - 7) continue;

        var q = [x, y];
        visited[lIdx] = 1;
        var qh = 0;
        var minX = x, maxX = x, minY = y, maxY = y, count = 0;

        while (qh < q.length){
          var cx = q[qh++], cy = q[qh++];
          count++;
          if (cx < minX) minX = cx; if (cx > maxX) maxX = cx;
          if (cy < minY) minY = cy; if (cy > maxY) maxY = cy;

          var nbs = [[cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]];
          for (var ni = 0; ni < 4; ni++){
            var nx = nbs[ni][0], ny = nbs[ni][1];
            if (nx >= x0 && nx < x1 && ny >= y0 && ny < y1){
              var nlIdx = (ny - y0) * winW + (nx - x0);
              if (!visited[nlIdx] && gray[ny * w + nx] < th){
                visited[nlIdx] = 1;
                q.push(nx, ny);
              }
            }
          }
        }

        // Loại bỏ các vết đen mép giấy quét dính sát viền ngoài
        if (minX <= 8 || maxX >= w - 9 || minY <= 8 || maxY >= h - 9) continue;

        var bw = maxX - minX + 1, bh = maxY - minY + 1;
        var fill = count / (bw * bh);
        var asp = bw / bh;

        if (bw >= minDim && bw <= maxDim && bh >= minDim && bh <= maxDim && fill >= 0.65 && asp >= 0.65 && asp <= 1.55){
          var zin = getZinSquareCenter(gray, w, h, minX, maxX, minY, maxY, th);
          var dist = Math.hypot(zin.cx - tx, zin.cy - ty);
          if (dist < minDist){
            minDist = dist;
            best = { cx: zin.cx, cy: zin.cy, bw: zin.bw, bh: zin.bh, dist: dist };
          }
        }
      }
    }
  }

  return best;
}

var BASE_CORNERS_A4_BGD = [[0.0501, 0.0401], [0.9433, 0.0401], [0.9433, 0.9450], [0.0501, 0.9450]];
/* GOC MAC DINH DA DONG BANG (thay chot 2026-11-07, KHONG thay doi trong moi phien ban sau):
   Goc 1 (0.0349, 0.0215) — Goc 2 (0.9532, 0.0215) — Goc 3 (0.9532, 0.9721) — Goc 4 (0.0349, 0.9721).
   Day la so lieu thay do; moi mau phieu khong nam trong danh sach A4 deu mac dinh dung bo nay. */
var BASE_CORNERS_OLM = [[0.0349, 0.0215], [0.9532, 0.0215], [0.9532, 0.9721], [0.0349, 0.9721]];

function getStandardCorners(tid){
  if (isOlmTemplate(tid)){
    return BASE_CORNERS_OLM.map(function(c){ return [c[0], c[1]]; });
  }
  return BASE_CORNERS_A4_BGD.map(function(c){ return [c[0], c[1]]; });
}

/* Khoang cach giua cac o den goc theo loai phieu — MHEdu chot 2026-11-06:
   A4_BGD: W=0.8932 (0.9433 - 0.0501), H=0.9049 (0.9450 - 0.0401)
   OLM_DenTrang: W=0.9183 (0.9532 - 0.0349), H=0.9506 (0.9721 - 0.0215) */
function cornerSpan(tid){
  if (isOlmTemplate(tid)){
    return { W: 0.9183, H: 0.9506 };
  }
  return { W: 0.8932, H: 0.9049 };
}

function detectSheetCorners(img, rot, baseCalib){
  try {
    var iw = img.naturalWidth || img.width, ih = img.naturalHeight || img.height;
    if (!iw || !ih) return null;

    var span = cornerSpan();
    var maxW = 1400;
    var d = drawPhotoToCanvas(img, rot || 0, maxW);
    var cv = d.cv, ctx = d.ctx;
    var w = cv.width, h = cv.height;
    if (w < 100 || h < 100) return null;
    var imgData = ctx.getImageData(0, 0, w, h);
    var data = imgData.data;

    // Chuyển sang mảng xám 1 byte
    var gray = new Uint8Array(w * h);
    for (var i = 0, j = 0; i < data.length; i += 4, j++){
      gray[j] = (data[i] * 299 + data[i + 1] * 587 + data[i + 2] * 114 + 500) / 1000 | 0;
    }

    // Nguyên tắc chốt toạ độ theo yêu cầu của thầy:
    // 1. Xác định góc 2 chuẩn trước là A(x2, y2) (Góc Trên - Phải)
    var c2 = findCornerByTarget(gray, w, h, 1);
    var x2 = null, y2 = null;
    if (c2){
      x2 = c2.cx / w;
      y2 = c2.cy / h;
    } else {
      // Nếu góc 2 bị mờ, thử tìm từ góc 3 hoặc góc 1
      var c3 = findCornerByTarget(gray, w, h, 2);
      if (c3){
        x2 = c3.cx / w;
        y2 = c3.cy / h - span.H;
      } else {
        var c1 = findCornerByTarget(gray, w, h, 0);
        if (c1){
          x2 = c1.cx / w + span.W;
          y2 = c1.cy / h;
        } else {
          return null;
        }
      }
    }

    // 2. Tọa độ chuẩn 4 góc vuông góc trực tiếp theo nhịp span cố định của phiếu:
    // Góc 2 chuẩn: A(x2, y2)
    // Góc 3: B(x2, y2 + span.H)
    // Góc 1: C(x2 - span.W, y2)
    // Góc 4: D(x2 - span.W, y2 + span.H)
    var x1 = x2 - span.W;
    var y1 = y2;
    var x3 = x2;
    var y3 = y2 + span.H;
    var x4 = x2 - span.W;
    var y4 = y2 + span.H;

    function cl(v){ return Math.round(Math.min(1, Math.max(0, v)) * 10000) / 10000; }
    return [
      [cl(x1), cl(y1)],
      [cl(x2), cl(y2)],
      [cl(x3), cl(y3)],
      [cl(x4), cl(y4)]
    ];
  } catch(e){
    console.warn('Lỗi detectSheetCorners:', e);
    return null;
  }
}

function detectCorners(img, rot){
  return detectSheetCorners(img, rot, S.calibShared || defaultCalib());
}

/* Chạy auto-detect cho 1 ảnh; nếu thành công thì đặt p.calib. Trả về true nếu tìm được 4 góc. */
function autoCalibPhoto(p){
  /* DA TAT 2026-11-07 (thay chot: dung goc co dinh da dong bang, khong do tu dong).
     Truoc day ham nay do 4 goc tu tung anh roi ghi de p.calib, nen o nhap goc hien
     so do duoc (VD 0.0438/0.9621) thay vi so thay do (0.0349/0.9532). */
  return false;
}
function defaultCalib(){
  var tidDef = S.exam && S.exam.templateId;
  return getStandardCorners(tidDef);
}
function photoCalib(p){
  var chkAuto = $('chkAutoAlignEach');
  var autoOn = !chkAuto || chkAuto.checked;
  if (!p) return S.calibShared || defaultCalib();
  /* Goc do tu dong cu (autoCalibOk) bi bo qua — ve goc code da dong bang (thay chot 2026-11-07).
     Chi goc thay chinh tay (autoCalibOk=false) moi duoc giu. */
  if (p.autoCalibOk){ p.calib = null; p.autoCalibOk = false; }
  if (autoOn){
    if (p.calib && p.autoCalibOk) return p.calib;
    if (autoCalibPhoto(p)) return p.calib;
  }
  var chkSame = $('chkSameCalib');
  if (chkSame && chkSame.checked && !autoOn){
    if (!S.calibShared) S.calibShared = defaultCalib();
    return S.calibShared;
  }
  if (p.calib) return p.calib;
  return S.calibShared || defaultCalib();
}
function rotatedSize(img, rot){
  // Bounding box của ảnh sau khi xoay góc bất kỳ (45/90/180/270...).
  // Với 90/180 cho kết quả đúng như cũ (hoán đổi / giữ nguyên); với 45 thì khung
  // phình ra đủ chứa ảnh xoay chéo, không bị cắt góc.
  var rad = rot * Math.PI / 180, c = Math.abs(Math.cos(rad)), sn = Math.abs(Math.sin(rad));
  return { w: Math.round(img.naturalWidth * c + img.naturalHeight * sn), h: Math.round(img.naturalWidth * sn + img.naturalHeight * c) };
}
function drawPhotoToCanvas(img, rot, maxW){
  var sz = rotatedSize(img, rot);
  var scale = Math.min(1, maxW / Math.max(sz.w, sz.h));
  var cw = Math.round(sz.w * scale), ch = Math.round(sz.h * scale);
  var cv = document.createElement('canvas'); cv.width = cw; cv.height = ch;
  var ctx = cv.getContext('2d');
  ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, cw, ch);
  ctx.translate(cw / 2, ch / 2); ctx.rotate(rot * Math.PI / 180);
  ctx.drawImage(img, -img.naturalWidth * scale / 2, -img.naturalHeight * scale / 2, img.naturalWidth * scale, img.naturalHeight * scale);
  return { cv: cv, ctx: ctx, scale: scale };
}
function sampleDarkness(imgData, W, px, py, rx, ry){
  var r = 0, dark = 0, tot = 0;
  var x0 = Math.max(0, Math.floor(px - rx)), x1 = Math.min(W - 1, Math.ceil(px + rx));
  var y0 = Math.max(0, Math.floor(py - ry)), y1 = Math.min(imgData.height - 1, Math.ceil(py + ry));
  for (var y = y0; y <= y1; y++){
    for (var x = x0; x <= x1; x++){
      var dx = (x - px) / rx, dy = (y - py) / ry;
      if (dx * dx + dy * dy > 1) continue;
      var idx = (y * W + x) * 4;
      var lum = (imgData.data[idx] + imgData.data[idx + 1] + imgData.data[idx + 2]) / 3;
      tot++; if (lum < 160) dark++;
    }
  }
  return tot ? dark / tot : 0;
}
function readPhoto(p){
  var G = curGrid();
  var maxW = 2200;
  var d = drawPhotoToCanvas(p.img, p.rot || 0, maxW);
  var cv = d.cv, ctx = d.ctx;
  var imgData = ctx.getImageData(0, 0, cv.width, cv.height);
  var calib = photoCalib(p);
  var quadPx = calib.map(function(c){ return [c[0] * cv.width, c[1] * cv.height]; });
  var H = solveHomography([[0, 0], [1, 0], [1, 1], [0, 1]], quadPx);
  // kích thước khung (px) để tính bán kính lấy mẫu
  var wq = (Math.hypot(quadPx[1][0] - quadPx[0][0], quadPx[1][1] - quadPx[0][1]) + Math.hypot(quadPx[2][0] - quadPx[3][0], quadPx[2][1] - quadPx[3][1])) / 2;
  var hq = (Math.hypot(quadPx[3][0] - quadPx[0][0], quadPx[3][1] - quadPx[0][1]) + Math.hypot(quadPx[2][0] - quadPx[1][0], quadPx[2][1] - quadPx[1][1])) / 2;
  var rx = G.radius * wq * 0.5, ry = G.radius * 0.707 * hq * 0.5;
  function D(fx, fy){
    var pt = applyH(H, fx, fy);
    return sampleDarkness(imgData, cv.width, pt[0], pt[1], Math.max(2, rx), Math.max(2, ry));
  }
  function pick(vals){
    // vals: mảng độ đậm; trả về {idx, max, second, uncertain}
    var order = vals.map(function(v, i){ return { v: v, i: i }; }).sort(function(a, b){ return b.v - a.v; });
    return { idx: order[0].i, max: order[0].v, second: order.length > 1 ? order[1].v : 0,
             uncertain: order[0].v < 0.55 || (order.length > 1 && order[1].v >= 0.45) };
  }
  var flags = [];
  // SBD: 8 slots, mỗi slot 10 chữ số (hàng = chữ số 0..9)
  var sbdChars = [];
  for (var s = 0; s < 8; s++){
    var vals = [];
    for (var dg = 0; dg < 10; dg++) vals.push(D(G.sbd[dg][s][0], G.sbd[dg][s][1]));
    var pk = pick(vals);
    var isFilled = (pk.max >= 0.44) || (pk.max >= 0.33 && (pk.max - pk.second) >= 0.08);
    if (!isFilled){ sbdChars.push('?'); flags.push('SBD thiếu ô ' + (s + 1)); }
    else {
      sbdChars.push(String(pk.idx));
      if (pk.uncertain) flags.push('SBD ô ' + (s + 1) + ' tô mờ / 2 ô');
    }
  }
  var sbd = sbdChars.join('');
  // Mã đề: 4 slots
  var madeChars = [];
  for (var s = 0; s < 4; s++){
    var vals = [];
    for (var dg = 0; dg < 10; dg++) vals.push(D(G.made[dg][s][0], G.made[dg][s][1]));
    var pk = pick(vals);
    var isFilled = (pk.max >= 0.44) || (pk.max >= 0.33 && (pk.max - pk.second) >= 0.08);
    if (!isFilled){ madeChars.push('?'); flags.push('Mã đề thiếu ô ' + (s + 1)); }
    else {
      madeChars.push(String(pk.idx));
      if (pk.uncertain) flags.push('Mã đề ô ' + (s + 1) + ' tô mờ / 2 ô');
    }
  }
  var made = madeChars.join('');
  var cfg = S.exam.config;
  // Phần I
  var p1 = [];
  for (var q = 0; q < cfg.n1; q++){
    if (q >= 40){ p1.push(null); continue; }
    var b = Math.floor(q / 10), r = q % 10;
    var vals = [];
    for (var o = 0; o < 4; o++) vals.push(D(G.pi[b][r][o][0], G.pi[b][r][o][1]));
    var pk = pick(vals);
    var isFilled = (pk.max >= 0.42) || (pk.max >= 0.32 && (pk.max - pk.second) >= 0.08);
    if (!isFilled) p1.push(null);
    else {
      p1.push('ABCD'[pk.idx]);
      if (pk.uncertain) flags.push('PI câu ' + (q + 1) + ' tô mờ / 2 ô');
    }
  }
  // Phần II
  var p2 = [];
  var is4Blk = G.pii && G.pii.length === 4;
  for (var q = 0; q < cfg.n2; q++){
    if (q >= 8){ p2.push([null, null, null, null]); continue; }
    var b = is4Blk ? Math.floor(q / 2) : q;
    var colD = (is4Blk && q % 2 === 1) ? 2 : 0;
    var colS = (is4Blk && q % 2 === 1) ? 3 : 1;
    var stmt = [];
    for (var st = 0; st < 4; st++){
      var ptD = G.pii[b] && G.pii[b][st] ? G.pii[b][st][colD] : null;
      var ptS = G.pii[b] && G.pii[b][st] ? G.pii[b][st][colS] : null;
      if (!ptD || !ptS){ stmt.push(null); continue; }
      var dD = D(ptD[0], ptD[1]);
      var dS = D(ptS[0], ptS[1]);
      if (dD < 0.30 && dS < 0.30) stmt.push(null);
      else if (dD >= 0.45 && dS >= 0.45){ stmt.push(null); flags.push('PII câu ' + (q + 1) + ' ý ' + 'abcd'[st] + ' tô cả Đ và S'); }
      else {
        stmt.push(dD >= dS ? 'D' : 'S');
        if (Math.max(dD, dS) < 0.55) flags.push('PII câu ' + (q + 1) + ' ý ' + 'abcd'[st] + ' tô mờ');
      }
    }
    p2.push(stmt);
  }
  // Phần III
  var p3 = [];
  for (var q = 0; q < cfg.n3; q++){
    var g = G.piii[q];
    if (!g){ p3.push(null); continue; }
    var minus = D(g.minus[0], g.minus[1]) >= 0.50;
    var cVals = g.commas.map(function(c){ return D(c[0], c[1]); });
    var commaPos = null;
    if (cVals[0] >= 0.50 && cVals[1] >= 0.50){ commaPos = cVals[0] >= cVals[1] ? 2 : 3; flags.push('PIII câu ' + (q + 1) + ' tô 2 dấu phẩy'); }
    else if (cVals[0] >= 0.50) commaPos = 2;
    else if (cVals[1] >= 0.50) commaPos = 3;
    var digits = [];
    for (var pos = 0; pos < 4; pos++){
      var vals = [];
      for (var dg = 0; dg < 10; dg++) vals.push(D(g.digits[dg][pos][0], g.digits[dg][pos][1]));
      var pk = pick(vals);
      // Chống nhận diện nhầm viền ô/nhiễu nền thành chữ số ảo (ví dụ tô 18 thành 1823):
      // Ô trống thường có pk.max ~0.28-0.32 và contrast < 0.08. Ô tô thật có độ đậm cao hoặc contrast >= 0.10.
      var isFilled = (pk.max >= 0.46) || (pk.max >= 0.35 && (pk.max - pk.second) >= 0.10);
      if (!isFilled) digits.push(null);
      else {
        digits.push(String(pk.idx));
        if (pk.uncertain) flags.push('PIII câu ' + (q + 1) + ' chữ số tô mờ');
      }
    }
    // cờ: khoảng trống giữa các chữ số
    var seenDigit = false, gap = false;
    for (var pos = 0; pos < 4; pos++){
      if (digits[pos] != null) seenDigit = true;
      else if (seenDigit && pos < 3 && digits[pos + 1] != null) gap = true;
    }
    if (gap) flags.push('PIII câu ' + (q + 1) + ' có khoảng trống giữa các chữ số');
    p3.push(p3Reconstruct(minus, commaPos, digits));
  }
  return { sbd: sbd, made: made, p1: p1, p2: p2, p3: p3, flags: flags };
}
function finalizeRead(p){
  var r = p.read;
  var stu = S.students.find(function(s){ return normSbd(s.sbd) === normSbd(r.sbd); }) ||
            S.students.find(function(s){ return normSbd(s.sbd).replace(/^0+/, '') === normSbd(r.sbd).replace(/^0+/, '') && normSbd(r.sbd).indexOf('?') < 0; });
  r.student = stu || null;
  if (!stu) r.flags.push('Chưa khớp học sinh (SBD lạ)');
  var key = S.keys[normMade(r.made)];
  if (!key || r.made.indexOf('?') >= 0){ r.keyMade = null; r.flags.push('Mã đề lạ / thiếu — chưa có đáp án cho mã này'); }
  else { r.keyMade = normMade(r.made); }
  if (key){
    var sc = scorePaper({ p1: r.p1, p2: r.p2, p3: r.p3 }, key, S.exam.config);
    r.score = sc;
  } else r.score = null;
  return r;
}

/* Xoay khung 180°: TL<->BR, TR<->BL, tọa độ (x,y) -> (1-x, 1-y).
   (Hàm này từng bị thiếu định nghĩa nên tính năng tự xoay 180° âm thầm lỗi — đã bổ sung 2026-11-05.) */
function rot180Calib(c){
  return [
    [1 - c[2][0], 1 - c[2][1]],
    [1 - c[3][0], 1 - c[3][1]],
    [1 - c[0][0], 1 - c[0][1]],
    [1 - c[1][0], 1 - c[1][1]]
  ];
}
/* ============ HỆ 7 KỊCH BẢN GÓC (thầy chốt khôi phục 7 kịch bản) ============
   Thử 7 kịch bản tịnh tiến 4 góc theo độ dịch chuyển d rồi chọn kết quả tốt nhất.
   - Phiếu A4_BGD: d = 0.0113 (mặc định)
   - Phiếu OLM_DenTrang: d = 0.005 (mặc định)
   Admin có thể tùy chỉnh d trong Admin tab, lưu vào settings/global trên Firebase. */
var SCENARIO_D_DEFAULT = 0.0113;
function getScenarioD(tid){
  var d = null;
  tid = tid || (S.exam && S.exam.templateId);
  var byTpl = S.settings && S.settings.scenarioDByTemplate;
  if (byTpl && tid && typeof byTpl[tid] === 'number') d = byTpl[tid];
  if (d == null && S.settings && typeof S.settings.scenarioD === 'number') d = S.settings.scenarioD;
  if (d != null && d > 0 && d <= 0.05) return d;
  return isOlmTemplate(tid) ? 0.005 : SCENARIO_D_DEFAULT;
}
/* Góc gốc từng loại phiếu (kịch bản 1) — do thầy chốt số liệu. */
var SCENARIO_BASE = {
  'A4_BGD': [[0.0487, 0.0423], [0.9447, 0.0423], [0.9447, 0.9461], [0.0487, 0.9461]],
  'a4tl': [[0.0487, 0.0423], [0.9447, 0.0423], [0.9447, 0.9461], [0.0487, 0.9461]],
  'bgd2025': [[0.0487, 0.0423], [0.9447, 0.0423], [0.9447, 0.9461], [0.0487, 0.9461]],
  'xPxDMlNvR1Oc6TVqonxC': [[0.0487, 0.0423], [0.9447, 0.0423], [0.9447, 0.9461], [0.0487, 0.9461]],
  'tr9fY91f6VZLZOFJczQb': [[0.0487, 0.0423], [0.9447, 0.0423], [0.9447, 0.9461], [0.0487, 0.9461]],
  'OLM_DenTrang': [[0.0534, 0.0363], [0.9465, 0.0363], [0.9465, 0.9485], [0.0534, 0.9485]],
  'wFAOnW2DLbBZOaXyo0Wh': [[0.0534, 0.0363], [0.9465, 0.0363], [0.9465, 0.9485], [0.0534, 0.9485]]
};

function getScenarioBase(tid){
  if (isOlmTemplate(tid)){
    return SCENARIO_BASE['OLM_DenTrang'];
  }
  return SCENARIO_BASE['A4_BGD'];
}
function buildScenarios(base, d){
  function shift(dx, dy){ return base.map(function(c){ return [c[0] + dx, c[1] + dy]; }); }
  /* Đúng chuẩn 7 kịch bản thầy yêu cầu:
     KB1: Gốc
     KB2: Tăng X thành X + d
     KB3: Giảm X thành X - d
     KB4: Tăng Y thành Y + d
     KB5: Giảm Y thành Y - d
     KB6: Tăng cả X và Y thành X + d và Y + d
     KB7: Giảm cả X và Y thành X - d và Y - d */
  var KB8_OFF = [[-0.0189, -0.0299], [0.0173, -0.0239], [0.0131, 0.0192], [-0.0034, 0.0192]];
  var KB9_OFF = [[-0.0189, -0.0241], [0.0173, -0.0231], [0.0033, 0.0200], [-0.0034, 0.0230]];
  function offCorners(off){ return base.map(function(c, i){ return [c[0] + off[i][0], c[1] + off[i][1]]; }); }
  return [
    shift(0, 0),    // KB1: gốc
    shift(d, 0),    // KB2: X + d
    shift(-d, 0),   // KB3: X - d
    shift(0, d),    // KB4: Y + d
    shift(0, -d),   // KB5: Y - d
    shift(d, d),    // KB6: X + d, Y + d
    shift(-d, -d),   // KB7: X - d, Y - d
    offCorners(KB8_OFF),  // KB8: lech theo tung goc (phieu lech 1)
    offCorners(KB9_OFF)   // KB9: lech theo tung goc (phieu lech 2)
  ];
}
/* Góc kịch bản 1 của phiếu hiện tại (bản sao để tránh sửa nhầm SCENARIO_BASE). */
function scenario1Calib(){
  var base = getScenarioBase();
  if (base) return base.map(function(c){ return [c[0], c[1]]; });
  return defaultCalib();
}
/* Đọc 1 lần với calib cho trước (không đổi p.calib vĩnh viễn), trả về r đã finalize. */
function readPhotoWithCalib(p, calib){
  var origCalib = p.calib, origOk = p.autoCalibOk, origShared = S.calibShared;
  p.calib = calib; p.autoCalibOk = true; S.calibShared = calib;
  try {
    var r = readPhoto(p);
    p.read = r; finalizeRead(p);
    return r;
  } finally {
    p.calib = origCalib; p.autoCalibOk = origOk; S.calibShared = origShared;
  }
}
/* Góc đang hiển thị trên màn hình (ảnh đang chọn) — làm góc gốc cho chấm tùy chỉnh. */
function screenCalib(){
  var p = S.photos[S.selPhoto];
  if (p){
    try { var c = photoCalib(p); return c.map(function(pt){ return [pt[0], pt[1]]; }); } catch(e){}
  }
  return scenario1Calib();
}
function scenarioBaseForPhoto(p){
  try {
    var code = getScenarioBase() || defaultCalib();
    if (p && p.calib && p.calib.length === 4 && code && code.length === 4 && !p.autoCalibOk){
      var dmax = 0;
      for (var k = 0; k < 4; k++) dmax = Math.max(dmax, Math.hypot(p.calib[k][0] - code[k][0], p.calib[k][1] - code[k][1]));
      if (dmax > 0.02) return p.calib; // thầy chỉnh tay góc riêng -> dùng luôn
    }
  } catch(e){}
  return null;
}

function sameSbd(a, b){
  a = String(a == null ? '' : a).trim();
  b = String(b == null ? '' : b).trim();
  if (!a || !b || a.indexOf('?') >= 0 || b.indexOf('?') >= 0) return false;
  return a.replace(/^0+/, '') === b.replace(/^0+/, '');
}

/* Đánh giá tổng thể và chọn kịch bản tối ưu nhất trong các kịch bản chạy thử:
   - Ưu tiên kịch bản đọc được Mã đề khớp trong đáp án (S.keys)
   - Ưu tiên kịch bản đọc được SBD khớp trong danh sách học sinh (S.students)
   - Đọc sạch SBD, Mã đề (không có '?', đủ ký tự)
   - Đọc được nhiều câu trả lời hợp lệ ở PI, PII, PIII
   - Điểm số bài thi cao nhất
   => Toàn bộ kết quả (SBD, Mã đề, P1, P2, P3) đồng nhất từ 1 kịch bản căn chỉnh chuẩn nhất,
      không bị ghép cọc cạch SBD kịch bản này với Mã đề kịch bản khác gây sai lệch. */
function dualPick(results){
  function evalScenario(x){
    if (!x || !x.r) return -99999;
    var r = x.r;
    var points = 0;
    
    // 1. Điểm bài thi nếu có (0 -> 10 điểm)
    var sc = scoreOf(r);
    if (typeof sc === 'number' && !isNaN(sc)) points += sc * 10;
    
    // 2. Khớp mã đề trong bảng đáp án S.keys
    if (r.keyMade && S.keys && S.keys[normMade(r.keyMade)]){
      points += 100;
    } else if (r.made && r.made.indexOf('?') < 0 && r.made.length >= 3){
      points += 30;
    } else {
      points -= 20;
    }
    
    // 3. Khớp học sinh trong danh sách S.students
    if (r.student){
      points += 60;
    } else if (r.sbd && r.sbd.indexOf('?') < 0 && r.sbd.replace(/^0+/, '').length >= 1){
      points += 20;
    } else {
      points -= 20;
    }
    
    // 4. Số câu có câu trả lời hợp lệ ở P1, P2, P3
    var ansCount = 0;
    if (Array.isArray(r.p1)) r.p1.forEach(function(a){ if (a) ansCount++; });
    if (Array.isArray(r.p2)) r.p2.forEach(function(st){ if (Array.isArray(st)) st.forEach(function(v){ if (v) ansCount++; }); });
    if (Array.isArray(r.p3)) r.p3.forEach(function(v){ if (v != null && v !== '') ansCount++; });
    points += ansCount * 2;
    
    // 5. Ưu tiên kịch bản gốc nếu các chỉ số tương đương
    points -= x.idx * 0.1;
    return points;
  }

  var best = null, bestScore = -999999;
  results.forEach(function(x){
    var pt = evalScenario(x);
    if (best === null || pt > bestScore){
      bestScore = pt;
      best = x;
    }
  });

  return { best: best ? best.r : null, bestIdx: best ? best.idx : 0 };
}

/* Chấm 1 ảnh theo các chế độ:
   - 'fast': Chấm nhanh = Kịch bản 1
   - 'medium': Chấm trung bình = Kịch bản 1, 2, 3, 4, 5
   - 'slow': Chấm chậm = Cả 7 kịch bản (1..7)
   - 'custom': Chấm tùy chỉnh = Căn góc trên màn hình + lưới tùy chỉnh phiên đó (cả 7 kịch bản) */
function gradePhotoScenarios(p, mode){
  var base = (mode === 'custom') ? screenCalib() : (scenarioBaseForPhoto(p) || getScenarioBase() || defaultCalib());
  var d = getScenarioD();
  var all = buildScenarios(base, d);
  var idxs = (mode === 'slow' || mode === 'custom') ? [0, 1, 2, 3, 4, 5, 6, 7, 8] : (mode === 'medium' ? [0, 1, 2, 3, 4] : [0]);
  
  var best = null, bestScore = -1, bestIdx = 0;
  var results = [];
  idxs.forEach(function(i){
    var r = readPhotoWithCalib(p, all[i]);
    results.push({ r: r, idx: i });
  });
  
  var picked = dualPick(results);
  best = picked.best; bestIdx = picked.bestIdx;
  bestScore = scoreOf(best); if (bestScore == null) bestScore = -1;
  
  // Kết quả tốt nhất vẫn bất thường (SBD/mã đề thiếu) → thử xoay 180° với góc kịch bản đó
  if (best && isAbnormalRead(best)){
    var rot = rot180Calib(all[bestIdx]);
    var origRot = p.rot || 0;
    p.rot = (origRot + 180) % 360;
    try {
      var r2 = readPhotoWithCalib(p, rot);
      if (scoreOf(r2) > bestScore){
        bestScore = scoreOf(r2); best = r2;
        best.autoRotated = true;
        best.flags.push('Đã tự xoay 180° để đọc (điểm cao hơn)');
      }
    } catch(e){}
    p.rot = origRot;
  }
  
  // Giữ góc cố định đã đóng băng làm calib của ảnh
  p.calib = JSON.parse(JSON.stringify(base)); p.autoCalibOk = false;
  p.read = best;
  return { r: best, scenario: bestIdx + 1 };
}
/* Quét tự xoay 180° (logic mới theo thầy):
   - SBD thường 6-8 ký tự, mã đề 3-4 ký tự.
   - Khi SBD/mã đề thiếu hoặc bất thường (ít ký tự) → chấm bình thường VÀ xoay 180° chấm nữa, lấy điểm cao hơn.
   - Chỉ bỏ qua khi cả 2 lần đều không có mã đề.
   - Đáp án các câu luôn được ghi lại để chấm lại. */
function isAbnormalRead(r){
  if (!r) return true;
  var sbdRaw = r.sbd || '', madeRaw = r.made || '';
  var sbdClean = sbdRaw.replace(/\?/g, '');
  var madeClean = madeRaw.replace(/\?/g, '');
  var sbdBad = sbdClean.length < 6 || sbdRaw.indexOf('?') >= 0;
  var madeBad = !r.keyMade || madeClean.length < 3;
  return sbdBad || madeBad;
}
function autoScoreVal(r){
  return (r && r.score && typeof r.score.scaled === 'number') ? r.score.scaled : -1;
}
function readPhotoAuto(p){
  var r1 = readPhoto(p); p.read = r1; finalizeRead(p);
  if (!isAbnormalRead(r1)) return r1; // đọc chuẩn, không cần xoay
  // Thử xoay 180° rồi chấm
  var origRot = p.rot || 0;
  var origCalib = p.calib;
  var origShared = S.calibShared;
  var sharedOn = false;
  var r2 = null;
  try {
    var chk = $('chkSameCalib'); sharedOn = !!(chk && chk.checked);
    var base = photoCalib(p);
    var rot = rot180Calib(base);
    p.rot = (origRot + 180) % 360;
    if (sharedOn) S.calibShared = rot; else p.calib = rot;
    r2 = readPhoto(p); p.read = r2; finalizeRead(p);
  } catch (e){ r2 = null; }
  p.rot = origRot;
  if (sharedOn) S.calibShared = origShared; else p.calib = origCalib;
  // So sánh điểm, lấy cao hơn
  var s1 = autoScoreVal(r1), s2 = autoScoreVal(r2);
  var best = (r2 && s2 > s1) ? r2 : r1;
  if (best && best.keyMade){
    if (best === r2){
      best.autoRotated = true;
      best.flags.push('Đã tự xoay 180° để đọc (điểm ' + s2 + ' cao hơn ' + s1 + ')');
    }
  } else {
    // Cả 2 đều không có mã đề → bỏ qua
    best = r1;
    if (best.flags.indexOf('Không đọc được mã đề (đã thử xoay 180°) — bỏ qua') < 0)
      best.flags.push('Không đọc được mã đề (đã thử xoay 180°) — bỏ qua');
  }
  p.read = best;
  return best;
}

/* Ảnh mẫu phiếu để nút 'Tải mẫu phiếu' tải về cho thầy in. Hệ thống mẫu phiếu mở: thêm mẫu mới sau này chỉ cần thêm 1 phần tử vào S.templates (id, name, grid) + lưới tương ứng trong GRIDS + 1 entry ảnh vào đây (nếu muốn tải được). */
var PHIEU_DOWNLOAD = {
  bgd2025: { name: 'MauPhieu_BGD2025.jpg', data: 'data:image/jpeg;base64,' },
  a4tl: { name: 'MauPhieu_A4BGD.jpg', data: 'data:image/jpeg;base64,' }
};
function resolvePhieuDownload(templateId){
  // Mẫu tự thêm: dùng ảnh đã tải lên lúc thêm mẫu. Mẫu gốc: dùng ảnh nhúng sẵn ở trên.
  var t = (S.templates || []).find(function(x){ return x.id === templateId; });
  if (t && t.img) return { name: 'MauPhieu_' + slugify(t.name) + '.jpg', data: t.img };
  return PHIEU_DOWNLOAD[templateId] || null;
}
function downloadPhieu(){
  var f = resolvePhieuDownload($('exTemplate').value);
  if (!f){ msg('examMsg', 'Mẫu phiếu này chưa có ảnh để tải. Mẫu tự thêm cần tải ảnh lên lúc thêm mẫu.', 'err'); return; }
  var a = document.createElement('a');
  a.href = f.data; a.download = f.name;
  document.body.appendChild(a); a.click(); a.remove();
  msg('examMsg', 'Đã tải mẫu phiếu <b>' + esc(f.name) + '</b> — thầy in ra cho học sinh làm bài.', 'okbox');
}
$('btnDlPhieu').onclick = function(){ downloadPhieu(); };
$('btnDlPhieuPdf').onclick = function(){ window.open('https://drive.google.com/drive/folders/1b8nd-YMwOBrRoTLGOPgzULVIOn2HNkXu?usp=sharing', '_blank'); };

/* ================= GRADING UI ================= */
// ---- Lọc theo lớp / Sắp xếp / Thống kê (tab Chấm bài) ----
function rowClass(r){ return (r && r.student && r.student.class) ? String(r.student.class) : ''; }
function scoreOf(r){ return (r && r.score && typeof r.score.scaled === 'number') ? r.score.scaled : null; }
function sbdKey(r){
  if (!r || !r.sbd || r.sbd.indexOf('?') >= 0) return null;
  return String(r.sbd).trim();
}
function cmpSbdStr(a, b){
  var na = parseFloat(a), nb = parseFloat(b);
  var aNum = a !== '' && !isNaN(na), bNum = b !== '' && !isNaN(nb);
  if (aNum && bNum && na !== nb) return na - nb;
  return String(a).localeCompare(String(b));
}
// rows: [{p, i, r}] — sắp xếp ỔN ĐỊNH theo chỉ số ảnh gốc; bài thiếu SBD/điểm/lớp luôn xếp cuối ở cả 2 chiều
function sortRows(rows, mode){
  rows.sort(function(A, B){
    var c = 0;
    if (mode === 'sbdAsc' || mode === 'sbdDesc'){
      var ma = sbdKey(A.r) === null, mb = sbdKey(B.r) === null;
      if (ma !== mb) return ma ? 1 : -1;
      if (!ma) c = cmpSbdStr(sbdKey(A.r), sbdKey(B.r));
      if (mode === 'sbdDesc') c = -c;
    } else if (mode === 'scoreAsc' || mode === 'scoreDesc'){
      var sa = scoreOf(A.r), sb = scoreOf(B.r);
      if (sa === null && sb === null) c = 0;
      else if (sa === null) return 1;
      else if (sb === null) return -1;
      else c = sa - sb;
      if (mode === 'scoreDesc') c = -c;
    } else if (mode === 'class'){
      var ca = rowClass(A.r), cb = rowClass(B.r);
      var mca = ca === '', mcb = cb === '';
      if (mca !== mcb) return mca ? 1 : -1;
      if (!mca) c = ca.localeCompare(cb);
      if (c === 0){
        var ka = sbdKey(A.r), kb = sbdKey(B.r);
        if (ka === null && kb === null) c = 0;
        else if (ka === null) return 1;
        else if (kb === null) return -1;
        else c = cmpSbdStr(ka, kb);
      }
    }
    return c !== 0 ? c : (A.i - B.i);
  });
}
function refreshGrClassOptions(){
  var sel = $('grClassFilter'); if (!sel) return;
  var cur = sel.value;
  var set = {};
  (S.students || []).forEach(function(s){ if (s.class) set[String(s.class)] = true; });
  (S.photos || []).forEach(function(p){ var c = rowClass(p.read); if (c) set[c] = true; });
  var classes = Object.keys(set).sort(function(a, b){ return a.localeCompare(b); });
  sel.innerHTML = '<option value="all">Tất cả các lớp</option>' + classes.map(function(c){ return '<option value="' + esc(c) + '">' + esc(c) + '</option>'; }).join('');
  sel.value = (cur === 'all' || classes.indexOf(cur) >= 0) ? cur : 'all';
}
function fmtNum(v, digits){
  var s = (Math.round(v * Math.pow(10, digits)) / Math.pow(10, digits)).toString();
  return s.replace('.', ',');
}
// Thống kê điểm theo 4 ngưỡng: dưới 50%, 50–<65%, 65–<80%, từ 80% thang điểm
function scoreBands(scores, scale){
  var t1 = scale * 0.5, t2 = scale * 0.65, t3 = scale * 0.8;
  var labels = ['Dưới ' + fmtNum(t1, 2), 'Từ ' + fmtNum(t1, 2) + ' đến dưới ' + fmtNum(t2, 2), 'Từ ' + fmtNum(t2, 2) + ' đến dưới ' + fmtNum(t3, 2), 'Từ ' + fmtNum(t3, 2) + ' trở lên'];
  var counts = [0, 0, 0, 0], sum = 0;
  scores.forEach(function(s){
    sum += s;
    if (s < t1) counts[0]++;
    else if (s < t2) counts[1]++;
    else if (s < t3) counts[2]++;
    else counts[3]++;
  });
  var total = scores.length;
  return {
    total: total,
    avg: total ? fmtNum(sum / total, 2) : '—',
    bands: labels.map(function(l, k){ return { label: l, count: counts[k], pct: total ? fmtNum(counts[k] / total * 100, 1) : '0' }; })
  };
}
function renderGrStats(){
  var box = $('grStats'); if (!box || !S.exam) return;
  var _scEl = $('grStatsScope'); var scope = _scEl ? _scEl.value : 'all';
  var scale = S.exam.config.scale;
  var scored = [];
  S.photos.forEach(function(p){
    var s = scoreOf(p.read);
    if (s !== null) scored.push({ score: s, cls: rowClass(p.read) });
  });
  if (!scored.length){ box.innerHTML = 'Chưa có bài nào được chấm điểm nên chưa thống kê được.'; return; }
  function bandLine(list){
    var st = scoreBands(list.map(function(x){ return x.score; }), scale);
    return st.total + ' bài đã chấm, điểm trung bình ' + st.avg + ' — ' + st.bands.map(function(b){ return b.label + ': <b>' + b.count + ' bài (' + b.pct + '%)</b>'; }).join(' • ');
  }
  if (scope === 'all'){
    box.innerHTML = '<b>Thống kê tất cả:</b> ' + bandLine(scored);
  } else {
    var groups = {};
    scored.forEach(function(x){ var k = x.cls || 'Chưa gán lớp'; (groups[k] = groups[k] || []).push(x); });
    var keys = Object.keys(groups).sort(function(a, b){ return a.localeCompare(b); });
    box.innerHTML = '<b>Thống kê theo lớp:</b><br>' + keys.map(function(k){ return 'Lớp ' + esc(k) + ': ' + bandLine(groups[k]); }).join('<br>');
  }
}
function renderGrading(){
  maybeShowRestoreBanner();
  if (!S.exam) return;
  var btg = $('btnSaveTemplateGrid');
  if (btg) btg.style.display = S.isAdmin ? '' : 'none';
  var gt = $('grTemplate');
  if (gt && S.templates && S.templates.length){
    var gList = adminTemplates();
    gt.innerHTML = gList.map(function(t){ return '<option value="' + t.id + '">' + esc(t.name) + '</option>'; }).join('');
    if (gList.some(function(t){ return t.id === S.exam.templateId; })) gt.value = S.exam.templateId;
    else gt.selectedIndex = -1;
    gt.onchange = async function(){
      var tid = this.value;
      try {
        await db.collection('exams').doc(S.exam.id).update({ templateId: tid, customGridJson: null });
        S.exam.templateId = tid; S.exam.customGridJson = null; S.exam._customGrid = null;
        S.liveGrid = null; S.gridEditorExamId = null; S.gridParams = null;
        S.calibShared = getStandardCorners(tid);
        S.photos.forEach(function(ph){ ph.calib = JSON.parse(JSON.stringify(S.calibShared)); ph.autoCalibOk = false; });
        var cc = $('calibCoords');
        if (cc) cc.dataset.bound = '';
        drawCalib(); renderGrading();
        msg('grMsg', 'Đã đổi sang mẫu phiếu <b>' + (gt.options[gt.selectedIndex] ? gt.options[gt.selectedIndex].text : tid) + '</b>. Tọa độ 4 góc và lưới đã cập nhật chuẩn.', 'okbox');
      } catch (e){ msg('grMsg', 'Lỗi đổi mẫu phiếu: ' + esc(e.message), 'err'); }
    };
  }
  $('photoCount').textContent = S.photos.length;
  var strip = $('photoStrip'); strip.innerHTML = '';
  var psize = S.photoPageSize || 10;
  // Ảnh đang chọn đổi thì nhảy về đúng trang chứa nó; bấm chuyển trang thì không nhảy lại.
  if (S.selPhoto >= 0 && S.selPhoto !== S.photoPageSelPhoto){
    S.photoPage = Math.floor(S.selPhoto / psize) + 1;
    S.photoPageSelPhoto = S.selPhoto;
  }
  var ppg = pageSlice(S.photos, S.photoPage || 1, psize);
  S.photoPage = ppg.page;
  ppg.items.forEach(function(p, k){
    var i = ppg.start + k;
    var im = document.createElement('img');
    im.src = p.img.src; im.className = 'photo-thumb' + (i === S.selPhoto ? ' sel' : '');
    im.title = p.name + (p.read ? ' — đã chấm' : ' — chưa chấm');
    im.onclick = function(){ S.selPhoto = i; renderGrading(); drawCalib(); };
    strip.appendChild(im);
  });
  strip.style.display = S.photoStripHidden ? 'none' : '';
  var pp = $('photoPager'); if (pp) pp.textContent = 'Trang ' + ppg.page + '/' + ppg.totalPages + ' (tổng ' + S.photos.length + ' ảnh)';
  var bt = $('btnTogglePhotos'); if (bt) bt.textContent = S.photoStripHidden ? 'Hiện ảnh' : 'Ẩn ảnh';
  if (S.photos.length && S.selPhoto < 0) S.selPhoto = 0;
  drawCalib();
  var gs = $('gridStatus');
  if (gs){
    curGrid(); // cập nhật S._gridSource
    if (S._gridSource) gs.textContent = 'Đang dùng: ' + S._gridSource;
    else {
    var tt = (S.templates || []).find(function(x){ return x.id === S.exam.templateId; });
    if (S.exam.customGridJson) gs.textContent = 'Đang dùng lưới riêng của bài (đã sửa tay)';
    else if (tt && tt.gridParamsJson) gs.textContent = tt._gridFromCode ? 'Đang dùng lưới mặc định cho loại phiếu này' : 'Đang dùng lưới chuẩn đã lưu cho loại phiếu này';
    else gs.textContent = 'Đang dùng lưới mẫu: ' + (gt && gt.selectedIndex >= 0 ? gt.options[gt.selectedIndex].text : '');
    }
  }
  if (S.gridEditorExamId !== S.exam.id){
    S.liveGrid = null;
    S.gridParams = gridToParams(curGrid());
    S.gridEditorExamId = S.exam.id;
    renderGridEditor();
  }
  var f = $('grFilter').value;
  refreshGrClassOptions();
  var _cfEl = $('grClassFilter'); var cls = _cfEl ? _cfEl.value : 'all';
  var _stEl = $('grSort'); var sort = _stEl ? _stEl.value : 'none';
  var tb = $('grTable'); tb.innerHTML = '';
  var rows = [];
  S.photos.forEach(function(p, i){
    var r = p.read;
    var show = true;
    if (f === 'sbd') show = r && (r.sbd.indexOf('?') >= 0 || !r.student);
    if (f === 'made') show = r && !r.keyMade;
    if (f === 'check') show = r && r.flags.some(function(x){ return /tô mờ|2 ô|2 dấu|khoảng trống|cả Đ và S/.test(x); });
    if (f === 'nomatch') show = r && !r.student;
    if (f === 'low') show = r && r.score && r.score.scaled < S.exam.config.scale / 2;
    if (f === 'done') show = r && !r.flags.length;
    if (cls !== 'all' && rowClass(r) !== cls) show = false;
    if (!show) return;
    rows.push({ p: p, i: i, r: r });
  });
  sortRows(rows, sort);
  rows.forEach(function(row){
    var p = row.p, i = row.i, r = row.r;
    var flagTxt = r ? r.flags.join('; ') : 'Chưa chấm';
    var tr = document.createElement('tr');
    if (r && r.flags.length) tr.className = 'flag';
    tr.innerHTML = '<td><b>' + (i + 1) + '</b></td><td>' + esc(p.name) + '</td><td>' + (r ? esc(r.sbd) : '—') + '</td><td>' + (r && r.student ? esc(r.student.name) + ' (' + esc(r.student.class || '') + ')' : '—') + '</td><td>' + (r ? esc(r.made) : '—') + '</td><td>' + (r && r.score ? r.score.scaled : '—') + '</td><td>' + esc(flagTxt) + '</td>' +
      '<td><button data-m="' + i + '">Chấm lại</button> <button class="danger" data-x="' + i + '">Xóa ảnh</button></td>';
    tr.querySelector('[data-m]').onclick = function(){ openManual(i); };
    tr.querySelector('[data-x]').onclick = function(){ S.photos.splice(i, 1); if (S.selPhoto >= S.photos.length) S.selPhoto = S.photos.length - 1; renderGrading(); };
    tb.appendChild(tr);
  });
  var _gsb = $('grStats'); if (_gsb && _gsb.style.display !== 'none') renderGrStats();
}
function pageSlice(arr, page, size){
  var sz = Math.max(1, size || 10);
  var tp = Math.max(1, Math.ceil(arr.length / sz));
  var pg = Math.min(Math.max(1, page || 1), tp);
  return { items: arr.slice((pg - 1) * sz, pg * sz), totalPages: tp, page: pg, start: (pg - 1) * sz };
}
$('grFilter').onchange = renderGrading;
// Cụm mới (lọc/sắp xếp/thống kê): vỏ cũ chưa có các id này thì bỏ qua, app vẫn chạy đủ phần còn lại
var _gcf = $('grClassFilter'); if (_gcf) _gcf.onchange = renderGrading;
var _gsrt = $('grSort'); if (_gsrt) _gsrt.onchange = renderGrading;
var _bgs = $('btnGrStats'); if (_bgs) _bgs.onclick = function(){
  var box = $('grStats');
  if (!box) return;
  if (box.style.display === 'none'){ renderGrStats(); box.style.display = 'block'; }
  else box.style.display = 'none';
};
var _gss = $('grStatsScope'); if (_gss) _gss.onchange = function(){ var b = $('grStats'); if (b && b.style.display !== 'none') renderGrStats(); };
$('btnPhotoPrev').onclick = function(){ S.photoPage = (S.photoPage || 1) - 1; renderGrading(); };
$('btnPhotoNext').onclick = function(){ S.photoPage = (S.photoPage || 1) + 1; renderGrading(); };
$('photoPageSize').onchange = function(){ S.photoPageSize = parseInt(this.value || 10); S.photoPage = 1; renderGrading(); };
$('btnTogglePhotos').onclick = function(){ S.photoStripHidden = !S.photoStripHidden; renderGrading(); };
$('filePhotos').onchange = function(){
  if (!needExam()) return;
  var files = Array.prototype.slice.call(this.files);
  if (!files.length) return;
  var _maxBatch = maxPhotosPerBatch();
  var room = _maxBatch - S.photos.length;
  if (room <= 0){ msg('grMsg', 'Đã đủ ' + _maxBatch + ' ảnh. Thầy chấm và lưu đợt này xong, bấm "Xóa hết ảnh" rồi tải đợt tiếp theo.', 'err'); this.value = ''; return; }
  if (files.length > room){ msg('grMsg', 'Mỗi lần chấm tối đa ' + _maxBatch + ' ảnh — chỉ lấy ' + room + ' ảnh đầu, còn lại thầy để đợt sau.', 'note'); files = files.slice(0, room); }
  var dd = dedupeUploadFiles(files, S.photos);
  files = dd.kept;
  if (!files.length){ msg('grMsg', 'Tất cả ảnh vừa chọn đều đã có trong đợt này (trùng tên + dung lượng) nên không thêm ảnh nào.', 'note'); this.value = ''; return; }
  var done = 0, addedN = 0;
  function oneDone(){
    if (++done < files.length) return;
    if (S.selPhoto < 0 && S.photos.length) S.selPhoto = 0;
    renderGrading();
    saveSessionNow();
    if (dd.dups) msg('grMsg', 'Đã thêm ' + addedN + ' ảnh, bỏ qua ' + dd.dups + ' ảnh trùng (cùng tên + dung lượng).', 'note');
  }
  files.forEach(function(f){
    var url = URL.createObjectURL(f);
    var im = new Image();
    im.onload = function(){
      var p = { name: f.name, img: im, blob: f, size: f.size, rot: 0, calib: null, read: null, autoCalibOk: false };
      var tid = S.exam && S.exam.templateId;
      var defC = S.calibShared || getStandardCorners(tid);
      p.calib = JSON.parse(JSON.stringify(defC));
      p.autoCalibOk = false;
      S.photos.push(p); addedN++; oneDone();
    };
    im.onerror = function(){ oneDone(); };
    im.src = url;
  });
  this.value = '';
};
function rotSel(delta){
  if (S.selPhoto < 0) return;
  var p = S.photos[S.selPhoto];
  var oldCalib = p.calib || scenario1Calib();
  p.rot = (p.rot + delta + 360) % 360; p.read = null;
  // Xoay 180° thì xoay luôn khung; xoay góc khác thì về mặc định kịch bản 1
  try { p.calib = (Math.abs(delta) === 180) ? rot180Calib(oldCalib) : scenario1Calib(); p.autoCalibOk = true; } catch(e){ p.calib = null; p.autoCalibOk = false; }
  renderGrading();
  drawCalib();
  saveSessionSoon();
}
$('btnRotL').onclick = function(){ rotSel(-90); };
$('btnRotR').onclick = function(){ rotSel(90); };
$('btnRot45').onclick = function(){ rotSel(45); };
/* 0811sua3: Nut "Xoa tat ca anh" o tab Bai kiem tra = xoa anh trong Cloud cua bai do.
   Sua 3 cho: (1) nhan tham so msgEl de thong bao hien dung tab goi nut (tab Bai kiem
   tra thi bao o examMsg, khong roi sang grMsg cua tab Cham bai dang an); (2) phan
   loai Cloudinary/Drive chi dua vao link chua 'cloudinary' hoac id chua '/' (public_id
   Cloudinary) — bo dieu kien id chua '_' vi ID file Drive cung co the chua '_' nen
   de nhan nham anh Drive thanh Cloudinary; (3) bo fallback cung 'oyorxtpa' cho cName
   (theo cach thay da doi o cac cho khac trong 6.js: moi GV dung Cloud rieng). */
async function deleteExamPhotosById(exId, msgEl){
  var ex = S.exams.find(function(x){ return x.id === exId; });
  if (!ex){
    try {
      var dEx = await db.collection('exams').doc(exId).get();
      if (dEx.exists) ex = Object.assign({ id: dEx.id }, dEx.data());
    } catch(e){}
  }
  var examName = (ex && ex.name) ? ex.name.trim() : (S.exam && S.exam.id === exId ? S.exam.name.trim() : 'Bài kiểm tra');
  var msgTarget = msgEl || ((S.exam && S.exam.id === exId && $('grMsg')) ? 'grMsg' : 'examMsg');

  msg(msgTarget, 'Đang quét danh sách ảnh của bài <b>' + esc(examName) + '</b>...', 'note');

  // 1. Quét tìm tất cả kết quả của bài kiểm tra này trong Firestore
  var rsSnap = await db.collection('exams').doc(exId).collection('results').get();
  var cldIds = [];
  var gdriveIds = [];

  rsSnap.forEach(function(d){
    var r = d.data() || {};
    var link = r.driveFileLink || r.driveLink || '';
    var id = r.driveFileId || r.driveId || '';
    if (!id && link && link.indexOf('cloudinary') >= 0){
      var m = link.match(/\/upload\/(?:v\d+\/)?(.+?)(?:\.[a-zA-Z0-9]+)?$/);
      if (m && m[1]) id = decodeURIComponent(m[1]);
    }
    if (id){
      if ((link && link.indexOf('cloudinary') >= 0) || id.indexOf('/') >= 0){
        cldIds.push({ docRef: d.ref, id: id, link: link });
      } else {
        gdriveIds.push({ docRef: d.ref, id: id });
      }
    }
  });

  // Gom thêm ảnh trong bộ nhớ nếu đang mở đúng bài này
  if (S.exam && S.exam.id === exId && S.photos && S.photos.length){
    S.photos.forEach(function(p){
      if (p.driveLink && p.driveLink.id){
        var pid = p.driveLink.id;
        var plink = p.driveLink.link || '';
        if (p.driveLink.provider === 'cloudinary' || plink.indexOf('cloudinary') >= 0 || pid.indexOf('/') >= 0){
          if (!cldIds.some(function(item){ return item.id === pid; })){
            cldIds.push({ docRef: null, id: pid, link: plink });
          }
        }
      }
    });
  }

  var cName = (S.cloudinaryCloudName || (S.user && S.user.cloudinaryCloudName) || localStorage.getItem('chambai_cname') || '').trim();
  var isCloudinary = cldIds.length > 0 || (!!cName && gdriveIds.length === 0);

  if (isCloudinary){
    var creds = await ensureCloudinaryApiCredentials();
    if (!creds){
      msg(msgTarget, 'Chưa có API Key & API Secret nên không xóa tự động được. Thầy nhập API Key & API Secret ở tab <b>Tài khoản & VIP</b> (mục Cloudinary) rồi bấm <b>Lưu cài đặt Cloudinary</b>, sau đó bấm nút xóa lại — hệ thống sẽ xóa trực tiếp trên Cloud.', 'err');
      return;
    }

    // Tự động quét thêm ảnh từ Cloudinary qua API theo tên/slug bài thi nếu Firestore chưa ghi nhận hoặc ghi nhận thiếu
    try {
      msg(msgTarget, 'Đang quét ảnh bài thi trên Cloudinary (' + creds.cloudName + ')...', 'note');
      var cloudPhotos = await fetchCloudinaryExamResources(creds.cloudName, creds.apiKey, creds.apiSecret, examName);
      if (cloudPhotos && cloudPhotos.length){
        cloudPhotos.forEach(function(cp){
          if (!cldIds.some(function(item){ return item.id === cp.id; })){
            var matchedDocRef = null;
            rsSnap.forEach(function(d){
              if (d.id && cp.id.indexOf(d.id) >= 0) matchedDocRef = d.ref;
            });
            cldIds.push({ docRef: matchedDocRef, id: cp.id, link: cp.link });
          }
        });
      }
    } catch(eScan){
      console.warn('Lỗi quét Cloudinary:', eScan);
    }

    if (!cldIds.length){
      msg(msgTarget, 'Bài <b>' + esc(examName) + '</b> hiện không có ảnh nào trên Cloud (' + creds.cloudName + ') hoặc trong kết quả.', 'note');
      return;
    }

    var cfCld = confirm(
      '⚠️ XÓA TẤT CẢ ẢNH CỦA KỲ THI [' + examName + '] TRÊN CLOUD (' + creds.cloudName + ')\n\n' +
      'Tìm thấy: ' + cldIds.length + ' ảnh đã lưu của bài này.\n\n' +
      'Hệ thống sẽ gửi lệnh XÓA VĨNH VIỄN toàn bộ các ảnh này trên Cloudinary và gỡ liên kết trong kết quả thi.\n\n' +
      'Thầy/Cô có chắc chắn muốn xóa không?'
    );
    if (!cfCld){
      msg(msgTarget, 'Đã hủy thao tác xóa ảnh.', 'note');
      return;
    }

    var deletedCount = 0, failCount = 0;
    msg(msgTarget, 'Đang xóa ảnh trên Cloudinary (' + creds.cloudName + '): 0/' + cldIds.length + '...', 'note');

    for (var i = 0; i < cldIds.length; i++){
      var item = cldIds[i];
      try {
        await cloudinaryDestroyPhoto(creds.cloudName, item.id, creds.apiKey, creds.apiSecret);
        deletedCount++;
      } catch(err){
        console.warn('Lỗi xóa ảnh Cloudinary:', item.id, err);
        if (err.message && (err.message.indexOf('not found') >= 0 || err.message.indexOf('404') >= 0)){
          deletedCount++;
        } else {
          failCount++;
        }
      }
      if ((i + 1) % 5 === 0 || i === cldIds.length - 1){
        msg(msgTarget, 'Đang xóa ảnh trên Cloudinary: ' + (i + 1) + '/' + cldIds.length + '...', 'note');
      }
    }

    // Dọn dẹp liên kết trong Firestore results
    try {
      var batch = db.batch(), countBatch = 0;
      cldIds.forEach(function(item){
        if (item.docRef){
          batch.update(item.docRef, { driveFileId: null, driveFileLink: null, driveLink: null });
          countBatch++;
        }
      });
      if (countBatch > 0) await batch.commit();
    } catch(e){}

    // Nếu bài đang mở, gỡ liên kết trong S.photos
    if (S.exam && S.exam.id === exId){
      S.photos.forEach(function(p){ p.driveLink = null; });
      renderGrading();
      saveSessionNow();
    }

    var resultMsg = 'Đã xóa hoàn tất ảnh của kỳ thi <b>' + esc(examName) + '</b> trên Cloudinary: <b>' + deletedCount + '</b> ảnh đã xóa' + (failCount ? ' (' + failCount + ' ảnh lỗi)' : '') + '.';
    msg(msgTarget, resultMsg, 'okbox');
    alert('Đã xóa hoàn tất ' + deletedCount + ' ảnh của bài kiểm tra [' + examName + '] trên Cloudinary (' + cName + ')!');
    return;
  }

  // Nếu dùng Google Drive
  var hasDrive = !!S.driveToken;
  if (!hasDrive){
    var wantConnect = confirm(
      'Hệ thống chưa kết nối Google Drive (hoặc phiên làm việc đã hết hạn).\n\n' +
      'Thầy/Cô có muốn kết nối Google Drive ngay để quét và xóa tất cả ảnh của kỳ thi [' + examName + '] không?'
    );
    if (wantConnect){
      try {
        await driveConnect();
        hasDrive = !!S.driveToken;
      } catch(e){
        msg(msgTarget, 'Không thể kết nối Google Drive: ' + esc(e.message), 'err');
        return;
      }
    } else {
      return;
    }
  }

  var cfDrv = confirm(
    '⚠️ XÓA TẤT CẢ ẢNH CỦA KỲ THI [' + examName + '] TRÊN GOOGLE DRIVE\n\n' +
    'Hệ thống sẽ quét và XÓA TẤT CẢ các file ảnh có tên bắt đầu bằng "' + examName + '_" trong thư mục "anhchamtracnghiem" trên Google Drive.\n\n' +
    'Hành động này không thể hoàn tác. Thầy/Cô có chắc chắn muốn xóa không?'
  );
  if (!cfDrv) return;

  var drvDelCount = 0, drvFailCount = 0;
  msg(msgTarget, 'Đang quét tìm các ảnh của kỳ thi <b>' + esc(examName) + '</b> trong thư mục <b>anhchamtracnghiem</b> trên Google Drive...', 'note');

  try {
    var folderId = await getOrCreateDriveFolder('anhchamtracnghiem').catch(function(){ return (S.driveFolderId || '').trim(); });
    var q = "trashed = false and name contains '" + examName.replace(/'/g, "\\'") + "'";
    if (folderId) q = "'" + folderId + "' in parents and " + q;
    var url = 'https://www.googleapis.com/drive/v3/files?q=' + encodeURIComponent(q) + '&pageSize=1000&fields=files(id,name)';
    var res = await fetch(url, { headers: { Authorization: 'Bearer ' + S.driveToken } });
    if (res.status === 401){
      S.driveToken = null;
      msg(msgTarget, 'Phiên kết nối Google Drive đã hết hạn — thầy cô vào tab Tài khoản bấm "Kết nối Google Drive" rồi thực hiện lại nhé.', 'err');
      return;
    }
    if (!res.ok) throw new Error('Drive API báo lỗi: ' + res.status);
    var data = await res.json();
    var files = (data.files || []).filter(function(f){
      return f.name && (f.name.indexOf(examName + '_') === 0 || f.name.indexOf(examName) === 0);
    });

    if (!files.length){
      msg(msgTarget, 'Không tìm thấy file ảnh nào bắt đầu bằng <b>' + esc(examName) + '</b> trong thư mục <b>anhchamtracnghiem</b> trên Google Drive.', 'note');
    } else {
      msg(msgTarget, 'Đã tìm thấy <b>' + files.length + '</b> ảnh của kỳ thi [' + esc(examName) + ']. Đang xóa...', 'note');
      for (var j = 0; j < files.length; j++){
        var f = files[j];
        try {
          var delRes = await fetch('https://www.googleapis.com/drive/v3/files/' + f.id, {
            method: 'DELETE',
            headers: { Authorization: 'Bearer ' + S.driveToken }
          });
          if (delRes.ok || delRes.status === 204 || delRes.status === 404){
            drvDelCount++;
          } else {
            drvFailCount++;
          }
        } catch(e){
          drvFailCount++;
        }
        if ((j + 1) % 5 === 0 || j === files.length - 1){
          msg(msgTarget, 'Đang xóa ảnh trên Drive: ' + (j + 1) + '/' + files.length + '...', 'note');
        }
      }
    }
  } catch(err){
    msg(msgTarget, 'Lỗi khi xóa ảnh trên Drive: ' + esc(err.message), 'err');
  }

  // Xóa liên kết ảnh trong kết quả Firestore của bài thi này nếu có
  try {
    var rsDrvSnap = await db.collection('exams').doc(exId).collection('results').get();
    var batchDrv = db.batch(), clearedBatch = 0;
    rsDrvSnap.forEach(function(d){
      var rData = d.data();
      if (rData.driveFileLink || rData.driveLink){
        batchDrv.update(d.ref, { driveFileLink: null, driveLink: null, driveFileId: null });
        clearedBatch++;
      }
    });
    if (clearedBatch > 0) await batchDrv.commit();
  } catch(e){}

  if (S.exam && S.exam.id === exId){
    S.photos.forEach(function(p){ p.driveLink = null; });
    renderGrading();
    saveSessionNow();
  }

  msg(msgTarget, 'Đã xóa hoàn tất ảnh của kỳ thi <b>' + esc(examName) + '</b>: <b>' + drvDelCount + '</b> ảnh đã xóa trên Drive' + (drvFailCount ? ' (' + drvFailCount + ' ảnh lỗi)' : '') + '.', 'okbox');
  alert('Đã xóa ' + drvDelCount + ' ảnh của kỳ thi [' + examName + '] trên Google Drive!');
}
