$('btnDriveAll').onclick = async function(){
  if (!S.photos.length){ msg('grMsg', 'Chưa có ảnh nào.', 'err'); return; }
  var cName = (S.cloudinaryCloudName || localStorage.getItem('chambai_cname') || '').trim();
  var cPreset = (S.cloudinaryPreset || localStorage.getItem('chambai_cpreset') || '').trim();
  if (!cName && !S.driveToken){
    msg('grMsg', 'Chưa cấu hình lưu ảnh — thầy vào tab “Tài khoản & VIP” để cài đặt Cloudinary (khuyên dùng - 25GB miễn phí, 100% không lỗi) hoặc kết nối Google Drive.', 'err');
    return;
  }
  var providerName = cName ? 'Cloudinary' : 'Google Drive';
  var ok = 0, fail = 0, done = 0, total = S.photos.length, stopped = false;
  msg('grMsg', 'Đang lưu lên ' + providerName + ': 0/' + total + ' ảnh...', 'note');
  // Tải song song 3 ảnh/lượt cho nhanh (ảnh nén 1400px, quality 0.8)
  async function uploadOne(p){
    if (stopped) return;
    try {
      var d = drawPhotoToCanvas(p.img, p.rot || 0, 1400);
      var blob = await new Promise(function(res){ d.cv.toBlob(res, 'image/jpeg', 0.8); });
      p.driveLink = await driveUploadImage(blob, driveFileName(p));
      ok++;
    } catch (e){
      fail++;
      if (e.message === 'TOKEN_EXPIRED') stopped = true;
    }
    done++;
    msg('grMsg', 'Đang lưu lên ' + providerName + ': ' + done + '/' + total + ' ảnh...', 'note');
  }
  var queue = S.photos.slice();
  async function worker(){
    while (queue.length && !stopped){
      var p = queue.shift();
      await uploadOne(p);
    }
  }
  await Promise.all([worker(), worker(), worker()]);
  renderGrading();

  // Đồng bộ ngay link ảnh vừa lưu vào Firestore results để học sinh xem được ảnh ngay
  if (S.exam && S.exam.id && ok > 0){
    try {
      var saveBatch = db.batch(), saveCount = 0;
      S.photos.forEach(function(p, idx){
        if (p.driveLink && p.driveLink.id){
          var docId = (p.read && p.read.student ? p.read.student.sbd : null) ||
            (p.read && p.read.sbd && p.read.sbd.indexOf('?') < 0 ? p.read.sbd : ('anh_' + idx));
          var ref = db.collection('exams').doc(S.exam.id).collection('results').doc(docId);
          saveBatch.set(ref, {
            driveFileId: p.driveLink.id,
            driveFileLink: p.driveLink.link,
            driveLink: p.driveLink.link
          }, { merge: true });
          saveCount++;
        }
      });
      if (saveCount > 0) await saveBatch.commit();
    } catch(eBatch){
      console.warn('Lỗi đồng bộ link ảnh vào Firestore:', eBatch);
    }
  }
  msg('grMsg', 'Lưu lên ' + providerName + ' hoàn tất: <b>' + ok + '</b> ảnh thành công' + (fail ? ', <b>' + fail + '</b> ảnh lỗi.' : '.') + ' Link ảnh đã được đồng bộ vào kết quả bài thi.', (ok && !fail) ? 'okbox' : 'note');
};
