// (gridToParams, paramsToGrid, gridBlockArr đã chuyển lên đầu file)
function propagateEdit(prm, block, field, value){
  // Tự điền theo ô vừa sửa, chỉ chạy về phía trước:
  // - Sửa Y0/DX/DY (field 1/2/3): các lô bên phải trong cùng 1 phần theo luôn.
  // - Sửa X0 (field 0): các lô cùng cột ở các phần bên dưới theo luôn.
  // - field: 0=X0, 1=Y0, 2=DX, 3=DY.
  var affected = [];
  function set(name, f){ var arr = gridBlockArr(prm, name); if (arr){ arr[f] = value; affected.push([name, f]); } }
  function groupOf(name){
    if (name === 'SBD' || name === 'MADE') return ['SBD', 'MADE'];
    var m = /^(PI|PII|PIII)(\d)$/.exec(name); if (!m) return null;
    if (m[1] === 'PI') return ['PI1', 'PI2', 'PI3', 'PI4'];
    if (m[1] === 'PII') return ['PII1', 'PII2', 'PII3', 'PII4'];
    return ['PIII1', 'PIII2', 'PIII3', 'PIII4', 'PIII5', 'PIII6'];
  }
  var V = { PI1: ['PII1', 'PIII1'], PII1: ['PIII1'], PI2: ['PII2', 'PIII2'], PII2: ['PIII2'], PI3: ['PII3', 'PIII3'], PII3: ['PIII3'], PI4: ['PII4', 'PIII4'], PII4: ['PIII4'] };
  if (field === 1 || field === 2 || field === 3){
    var grp = groupOf(block);
    if (grp){ var idx = grp.indexOf(block); for (var k = idx + 1; k < grp.length; k++) set(grp[k], field); }
  }
  if (field === 0){ (V[block] || []).forEach(function(name){ set(name, 0); }); }
  return affected;
}
/* ================= TỰ ĐỘNG KHỚP Ô TRÒN VÀ TINH CHỈNH LƯỚI ================= */
S.gridStepSize = 0.0005;

/* Tìm tâm chuẩn của ô tròn (viền đen hoặc ô đã tô đen) gần vị trí dự đoán approxX, approxY */
function findBubbleCenter(imgData, approxX, approxY, rPx){
  var w = imgData.width, h = imgData.height, d = imgData.data;
  var bestX = Math.round(approxX), bestY = Math.round(approxY), bestScore = -1e9;
  var searchR = Math.max(6, Math.min(16, Math.round(rPx * 0.95)));
  var numAngles = 16;
  
  for (var dy = -searchR; dy <= searchR; dy++){
    for (var dx = -searchR; dx <= searchR; dx++){
      var cx = Math.round(approxX + dx);
      var cy = Math.round(approxY + dy);
      if (cx < rPx * 2 || cx >= w - rPx * 2 || cy < rPx * 2 || cy >= h - rPx * 2) continue;
      
      var ringDarkness = 0;
      var outerLightness = 0;
      for (var a = 0; a < numAngles; a++){
        var ang = a * (6.2831853 / numAngles);
        var rx = Math.round(cx + rPx * Math.cos(ang));
        var ry = Math.round(cy + rPx * Math.sin(ang));
        var ridx = (ry * w + rx) * 4;
        ringDarkness += (255 - (d[ridx] * 0.299 + d[ridx+1] * 0.587 + d[ridx+2] * 0.114));
        
        var ox = Math.round(cx + (rPx + 5) * Math.cos(ang));
        var oy = Math.round(cy + (rPx + 5) * Math.sin(ang));
        var oidx = (oy * w + ox) * 4;
        outerLightness += (d[oidx] * 0.299 + d[oidx+1] * 0.587 + d[oidx+2] * 0.114);
      }
      
      var score = ringDarkness + outerLightness * 0.45 - Math.hypot(dx, dy) * 1.8;
      if (score > bestScore){
        bestScore = score;
        bestX = cx;
        bestY = cy;
      }
    }
  }
  return [bestX, bestY];
}

/* Tự động khớp 4 ô đầu của 1 lô và tính lại X0, Y0, DX, DY */
function autoAlignBlock(blockName, p){
  if (!p || !p.img) return false;
  if (!S.gridParams) S.gridParams = gridToParams(curGrid());
  var prm = S.gridParams;
  var arr = gridBlockArr(prm, blockName);
  if (!arr) return false;
  
  var d = drawPhotoToCanvas(p.img, p.rot || 0, 1400);
  var cv = d.cv, ctx = d.ctx;
  var imgData = ctx.getImageData(0, 0, cv.width, cv.height);
  var calib = photoCalib(p);
  var quadPx = calib.map(function(c){ return [c[0] * cv.width, c[1] * cv.height]; });
  var H = solveHomography([[0, 0], [1, 0], [1, 1], [0, 1]], quadPx);
  var H_inv = solveHomography(quadPx, [[0, 0], [1, 0], [1, 1], [0, 1]]);
  
  var wq = (Math.hypot(quadPx[1][0] - quadPx[0][0], quadPx[1][1] - quadPx[0][1]) + Math.hypot(quadPx[2][0] - quadPx[3][0], quadPx[2][1] - quadPx[3][1])) / 2;
  var rPx = Math.max(5, Math.round(wq * (prm.RADIUS || 0.0075)));
  
  var x0 = arr[0], y0 = arr[1], dx = arr[2], dy = arr[3];
  var testPoints = [];
  if (blockName.startsWith('PIII')){
    testPoints = [
      [x0, y0 + 2 * dy],
      [x0 + dx, y0 + 2 * dy],
      [x0, y0 + 3 * dy],
      [x0 + dx, y0 + 3 * dy]
    ];
  } else {
    testPoints = [
      [x0, y0],
      [x0 + dx, y0],
      [x0, y0 + dy],
      [x0 + dx, y0 + dy]
    ];
  }
  
  var detectedNorm = [];
  for (var k = 0; k < 4; k++){
    var ptPx = applyH(H, testPoints[k][0], testPoints[k][1]);
    var foundPx = findBubbleCenter(imgData, ptPx[0], ptPx[1], rPx);
    var foundNorm = applyH(H_inv, foundPx[0], foundPx[1]);
    detectedNorm.push(foundNorm);
  }
  
  var newX0, newY0, newDX, newDY;
  if (blockName.startsWith('PIII')){
    newX0 = detectedNorm[0][0];
    newDX = Math.max(0.008, Math.min(0.05, ((detectedNorm[1][0] - detectedNorm[0][0]) + (detectedNorm[3][0] - detectedNorm[2][0])) / 2));
    newDY = Math.max(0.008, Math.min(0.05, ((detectedNorm[2][1] - detectedNorm[0][1]) + (detectedNorm[3][1] - detectedNorm[1][1])) / 2));
    newY0 = detectedNorm[0][1] - 2 * newDY;
  } else {
    newX0 = detectedNorm[0][0];
    newY0 = detectedNorm[0][1];
    newDX = Math.max(0.008, Math.min(0.08, ((detectedNorm[1][0] - detectedNorm[0][0]) + (detectedNorm[3][0] - detectedNorm[2][0])) / 2));
    newDY = Math.max(0.008, Math.min(0.08, ((detectedNorm[2][1] - detectedNorm[0][1]) + (detectedNorm[3][1] - detectedNorm[1][1])) / 2));
  }
  
  arr[0] = Math.round(newX0 * 10000) / 10000;
  arr[1] = Math.round(newY0 * 10000) / 10000;
  arr[2] = Math.round(newDX * 10000) / 10000;
  arr[3] = Math.round(newDY * 10000) / 10000;
  return true;
}

/* Tự động khớp toàn bộ các lô với ảnh đang chọn */
function autoAlignAllBlocks(p){
  if (!p || !p.img) return 0;
  var blocks = ['SBD', 'MADE', 'PI1', 'PI2', 'PI3', 'PI4', 'PII1', 'PII2', 'PII3', 'PII4', 'PIII1', 'PIII2', 'PIII3', 'PIII4', 'PIII5', 'PIII6'];
  var count = 0;
  blocks.forEach(function(b){
    if (autoAlignBlock(b, p)) count++;
  });
  if (count > 0){
    S.liveGrid = paramsToGrid(S.gridParams);
    renderGridEditor();
    drawCalib();
  }
  return count;
}

function renderGridEditor(){
  var ed = $('gridEditor'); if (!ed || !S.gridParams) return;
  var prm = S.gridParams;
  function inp(block, field, val){
    return '<input type="number" step="0.0001" value="' + val.toFixed(4) + '" data-block="' + block + '" data-field="' + field + '" style="width:68px;padding:2px 4px;font-size:12px">';
  }
  function nudge(block, field, dir, icon, title){
    return '<button type="button" class="secondary" data-nudge-block="' + block + '" data-nudge-field="' + field + '" data-nudge-dir="' + dir + '" title="' + title + '" style="padding:1px 5px;font-size:11px;min-width:20px;line-height:1.2">' + icon + '</button>';
  }
  function colControl(block, field, val, leftIcon, rightIcon, leftTitle, rightTitle){
    return '<div style="display:inline-flex;align-items:center;gap:2px">' +
      inp(block, field, val) +
      nudge(block, field, -1, leftIcon, leftTitle) +
      nudge(block, field, 1, rightIcon, rightTitle) +
      '</div>';
  }
  function row(name, arr){
    return '<tr>' +
      '<td><b>' + name + '</b></td>' +
      '<td>' + colControl(name, 0, arr[0], '◀', '▶', 'Dịch sang trái', 'Dịch sang phải') + '</td>' +
      '<td>' + colControl(name, 1, arr[1], '▲', '▼', 'Dịch lên trên', 'Dịch xuống dưới') + '</td>' +
      '<td>' + colControl(name, 2, arr[2], '-', '+', 'Thu hẹp ngang', 'Giãn rộng ngang') + '</td>' +
      '<td>' + colControl(name, 3, arr[3], '-', '+', 'Thu hẹp dọc', 'Giãn rộng dọc') + '</td>' +
      '<td style="white-space:nowrap">' +
        '<button type="button" class="ok" data-snap-block="' + name + '" title="Tự động khớp 4 ô đầu của lô này" style="padding:2px 7px;font-size:11px;font-weight:bold">🎯 Khớp</button> ' +
        '<button type="button" class="secondary" data-reset="' + name + '" title="Khôi phục" style="padding:2px 6px;font-size:11px">↩</button>' +
      '</td>' +
    '</tr>';
  }
  var h = '<table><thead><tr><th>Lô</th><th>X0 (ngang)</th><th>Y0 (dọc)</th><th>DX (sang phải)</th><th>DY (xuống dưới)</th><th>Thao tác</th></tr></thead><tbody>';
  h += row('SBD', prm.SBD) + row('MADE', prm.MADE);
  for (var b = 0; b < 4; b++) h += row('PI' + (b + 1), prm.PI[b]);
  for (var b2 = 0; b2 < 4; b2++) h += row('PII' + (b2 + 1), prm.PII[b2]);
  for (var q = 0; q < 6; q++) h += row('PIII' + (q + 1), prm.PIII[q]);
  h += '<tr><td><b>Bán kính ô</b></td><td colspan="4">' + inp('RADIUS', 0, prm.RADIUS) + ' <span class="muted" style="font-size:11px">(mặc định 0.0075)</span></td><td></td></tr></tbody></table>';
  ed.innerHTML = h;

  // Bind global step buttons
  document.querySelectorAll('.btn-step-val').forEach(function(b){
    if (b.dataset.bound) return;
    b.dataset.bound = '1';
    b.onclick = function(){
      document.querySelectorAll('.btn-step-val').forEach(function(x){
        x.style.border = '';
        x.style.fontWeight = 'normal';
      });
      b.style.border = '2px solid #2563eb';
      b.style.fontWeight = 'bold';
      S.gridStepSize = parseFloat(b.dataset.val) || 0.0005;
    };
  });

  // Bind auto snap all button
  var snapBtn = $('btnAutoSnapGrid');
  if (snapBtn && !snapBtn.dataset.bound){
    snapBtn.dataset.bound = '1';
    snapBtn.onclick = function(){
      if (S.selPhoto < 0 || !S.photos[S.selPhoto]){
        msg('grMsg', 'Thầy bấm chọn một ảnh ở dãy ảnh phía dưới trước để khớp.', 'err');
        return;
      }
      var p = S.photos[S.selPhoto];
      var cnt = autoAlignAllBlocks(p);
      if (cnt > 0){
        msg('grMsg', '🎯 Đã tự động khớp <b>' + cnt + '</b> lô với các ô tròn trên ảnh!', 'okbox');
      } else {
        msg('grMsg', 'Không khớp được. Thầy kiểm tra lại 4 góc đỏ có đúng 4 góc phiếu chưa.', 'err');
      }
    };
  }

  if (!ed.dataset.bound){
    ed.dataset.bound = '1';
    ed.addEventListener('input', function(e){
      var t = e.target; if (!t.dataset || t.dataset.field === undefined || !S.gridParams) return;
      var v = parseFloat(t.value); if (isNaN(v)) return;
      var affected = [];
      if (t.dataset.block === 'RADIUS'){ S.gridParams.RADIUS = v; }
      else {
        var arr = gridBlockArr(S.gridParams, t.dataset.block); if (!arr) return;
        arr[+t.dataset.field] = v;
        affected = propagateEdit(S.gridParams, t.dataset.block, +t.dataset.field, v);
        affected.forEach(function(a){
          var inp2 = ed.querySelector('input[data-block="' + a[0] + '"][data-field="' + a[1] + '"]');
          if (inp2) inp2.value = v.toFixed(4);
        });
      }
      S.liveGrid = paramsToGrid(S.gridParams);
      drawCalib();
      var st = $('gridEditStatus');
      if (st) st.textContent = affected.length ? 'Đã sửa và tự điền ' + affected.length + ' ô cùng phần/cột — bấm "Lưu lưới này cho bài" để giữ lại.' : 'Đã sửa (chưa lưu) — bấm "Đọc thử" để kiểm tra, "Lưu lưới này cho bài" để giữ lại.';
    });

    ed.addEventListener('click', function(e){
      var t = e.target;
      // Nudge button
      var nb = t.closest ? t.closest('[data-nudge-block]') : null;
      if (nb && S.gridParams){
        var block = nb.dataset.nudgeBlock;
        var field = parseInt(nb.dataset.nudgeField);
        var dir = parseFloat(nb.dataset.nudgeDir);
        var step = S.gridStepSize || 0.0005;
        var delta = (field >= 2) ? (step * 0.5) * dir : step * dir;
        var arr = gridBlockArr(S.gridParams, block);
        if (arr){
          arr[field] = Math.round((arr[field] + delta) * 10000) / 10000;
          propagateEdit(S.gridParams, block, field, arr[field]);
          S.liveGrid = paramsToGrid(S.gridParams);
          renderGridEditor();
          drawCalib();
          var st = $('gridEditStatus');
          if (st) st.textContent = 'Đã chỉnh ' + block + ' (' + (delta > 0 ? '+' : '') + delta.toFixed(4) + ').';
        }
        return;
      }
      
      // Snap block button
      var sb = t.closest ? t.closest('[data-snap-block]') : null;
      if (sb && S.gridParams){
        var snapName = sb.dataset.snapBlock;
        if (S.selPhoto < 0 || !S.photos[S.selPhoto]){
          msg('grMsg', 'Thầy chọn 1 ảnh ở dãy ảnh phía dưới trước.', 'err');
          return;
        }
        var p = S.photos[S.selPhoto];
        if (autoAlignBlock(snapName, p)){
          S.liveGrid = paramsToGrid(S.gridParams);
          renderGridEditor();
          drawCalib();
          msg('grMsg', 'Đã tự động khớp 4 ô đầu của lô <b>' + snapName + '</b> với ảnh!', 'okbox');
        } else {
          msg('grMsg', 'Không tự động khớp được lô ' + snapName + '.', 'err');
        }
        return;
      }

      // Reset button
      var rb = t.closest ? t.closest('[data-reset]') : null; if (!rb || !S.gridParams) return;
      var name = rb.dataset.reset;
      var keepLive = S.liveGrid; S.liveGrid = null; var saved = curGrid(); S.liveGrid = keepLive;
      var sp = gridToParams(saved);
      var dst = gridBlockArr(S.gridParams, name), src = gridBlockArr(sp, name);
      if (dst && src) for (var k = 0; k < 4; k++) dst[k] = src[k];
      S.liveGrid = paramsToGrid(S.gridParams);
      renderGridEditor(); drawCalib();
    });
  }
}
function buildParamsTxt(prm){
  var L = [];
  L.push('# LUOI CHAM THAM SO — xuat tu app');
  L.push('# Moi lo: TEN X0 Y0 DX DY (X0,Y0 = o goc tren-trai; DX = buoc sang phai; DY = buoc xuong duoi)');
  L.push('RADIUS ' + prm.RADIUS.toFixed(4));
  function line(name, a){ L.push(name + ' ' + a.map(function(v){ return v.toFixed(4); }).join(' ')); }
  line('SBD', prm.SBD); line('MADE', prm.MADE);
  for (var b = 0; b < 4; b++) line('PI' + (b + 1), prm.PI[b]);
  for (var b2 = 0; b2 < 4; b2++) line('PII' + (b2 + 1), prm.PII[b2]);
  for (var q = 0; q < 6; q++) line('PIII' + (q + 1), prm.PIII[q]);
  return L.join('\n') + '\n';
}
