$('btnTrialRead').onclick = async function(){
  if (!needExam()) return;
  if (S.selPhoto < 0 || !S.photos[S.selPhoto]){ msg('grMsg', 'Thầy bấm vào một ảnh ở dãy ảnh để chọn nó trước.', 'err'); return; }
  if (!Object.keys(S.keys).length){ msg('grMsg', 'Chưa có đáp án. Thầy sang tab Đáp án import đáp án trước.', 'err'); return; }
  var limited1 = freeLimited(), used1 = 0;
  if (limited1){
    try { used1 = await getGradeUsedToday(); }
    catch (e){ msg('grMsg', 'Không kiểm tra được lượt chấm hôm nay, thầy thử lại nhé. (Lỗi: ' + esc(e.message) + ')', 'err'); return; }
    if (used1 >= FREE_MAX_GRADES_PER_DAY){ msg('grMsg', 'Tài khoản thường chỉ chấm 10 bài/ngày. Hôm nay thầy đã chấm đủ 10 bài rồi. Thầy nâng cấp VIP để chấm không giới hạn.', 'err'); return; }
  }
  if (!(await checkYearlyLimit(1))) return;
  var p = S.photos[S.selPhoto];
  try {
    if (!p.calib || !p.autoCalibOk){ try { autoCalibPhoto(p); } catch(_ce){} }
    var r = readPhotoAuto(p);
    if (limited1){ try { await addGradeUsedToday(1); } catch (e){} }
    try { await addGradeUsedYear(1); } catch(e){}
    renderGrading();
    saveSessionNow();
    msg('grMsg', 'Đọc thử <b>' + esc(p.name) + '</b>: SBD <b>' + esc(r.sbd) + '</b>, mã đề <b>' + esc(r.made) + '</b>' +
      (r.student ? ', khớp ' + esc(r.student.name) : ' (chưa khớp học sinh)') +
      (r.keyMade ? ', có đáp án mã ' + esc(S.keys[r.keyMade].made) : ' (mã đề lạ)') +
      (r.flags.length ? '<br>Cờ: ' + esc(r.flags.join('; ')) : '<br>Không có cờ — căn khung chuẩn!') + (limited1 ? '<br>Tài khoản thường: ' + (used1 + 1) + '/10 bài hôm nay.' : ''), r.flags.length ? 'note' : 'okbox');
  } catch (e){ msg('grMsg', 'Lỗi đọc thử: ' + esc(e.message), 'err'); }
};
/* 4 nút chế độ chấm (15 kịch bản góc) — bind null-safe để vỏ cũ không lỗi */
function gradeSelectedWithMode(mode, modeLabel){
  if (!needExam()) return;
  if (!Object.keys(S.keys).length){ msg('grMsg', 'Chưa có đáp án. Thầy sang tab Đáp án import đáp án trước.', 'err'); return; }
  S.gradeMode = mode;
  updateGradeModeButtons();
  if (mode === 'custom'){
    // Chấm tùy chỉnh: áp dụng cho TẤT CẢ ảnh, thử cả 7 kịch bản, căn góc và lưới hiện tại trên màn hình
    gradeAllPhotos('custom', 'tùy chỉnh (căn góc và lưới trên màn hình)');
    return;
  }
  if (S.selPhoto < 0 || !S.photos[S.selPhoto]){ msg('grMsg', 'Thầy chọn 1 ảnh trước nhé.', 'err'); return; }
  var p = S.photos[S.selPhoto];
  try {
    msg('grMsg', 'Đang chấm ' + modeLabel + '...', 'note');
    var gr = gradePhotoScenarios(p, mode);
    var r = gr.r;
    renderGrading(); saveSessionNow();
    msg('grMsg', 'Đã chấm ' + modeLabel + ' ảnh <b>' + esc(p.name) + '</b>: ' + (r.score ? r.score.scaled + ' điểm' : 'chưa có điểm') + (gr.scenario ? ' (kịch bản ' + gr.scenario + ' thắng)' : ' (góc tùy chỉnh trên màn hình)') + (r.flags.length ? '<br>Cờ: ' + esc(r.flags.join('; ')) : ''), 'okbox');
  } catch (e){ msg('grMsg', 'Lỗi chấm: ' + esc(e.message), 'err'); }
}
function updateGradeModeButtons(){
  var modes = { btnGradeFast: 'fast', btnGradeMedium: 'medium', btnGradeSlow: 'slow', btnGradeCustom: 'custom' };
  Object.keys(modes).forEach(function(id){
    var b = $(id);
    if (b) b.className = (S.gradeMode === modes[id]) ? 'ok' : 'secondary';
  });
}
(function(){
  var b1 = $('btnGradeFast'); if (b1) b1.onclick = function(){ gradeSelectedWithMode('fast', 'nhanh'); };
  var b2 = $('btnGradeMedium'); if (b2) b2.onclick = function(){ gradeSelectedWithMode('medium', 'trung bình'); };
  var b3 = $('btnGradeSlow'); if (b3) b3.onclick = function(){ gradeSelectedWithMode('slow', 'chậm'); };
  var b4 = $('btnGradeCustom'); if (b4) b4.onclick = function(){ gradeSelectedWithMode('custom', 'tùy chỉnh'); };
  updateGradeModeButtons();
})();
